# Stories for albums 151–200 (long format agreed with the owner: three paragraphs + a listening tip,
# ~250 words, three picks). Original Hebrew; facts checked on the web, uncertain ones softened.
# Used by tools/batches/build_151_200.py; later edits: python3 tools/apply_stories.py stories_151_200
STORIES = {}
def add(n, story, picks): STORIES[n] = {'story': story, 'picks': picks}

add(151, [
'''בסוף שנות השישים אלביס פרסלי כבר נחשב לכוכב של אתמול: שנים של סרטים הוליוודיים בינוניים ופסקולים חסרי חיים הרחיקו אותו מהמוזיקה שהפכה אותו למלך (אלבומים 2 ו־25). תוכנית הקאמבק שלו בטלוויזיה בסוף 1968 הזכירה לכולם מה הוא מסוגל לעשות, ובתחילת 1969 הוא נכנס, לראשונה מזה יותר מעשור, לאולפן בעיר שלו ממפיס: אולפן American Sound של המפיק צ׳יפס מומן, עם להקת הבית המיומנת שלו.''',
'''הצליל הוא סול דרומי חם, עם קאנטרי וגוספל: פסנתר, אורגן, כלי נשיפה, זמרות ליווי, ומעל כולם קול בוגר, עמוק ורציני בהרבה מזה של אלביס הצעיר. הוא שר כאן שירים של כותבים עכשוויים ולא פזמונים של סרטים. In the Ghetto הוא שיר מחאה חברתי עדין על ילד שנולד לעוני בשכונה עניה בשיקגו, Long Black Limousine הוא סיפור קודר על נערה שחוזרת לעיירה שלה בארון מתים, ו־Only the Strong Survive, להיט סול של ג׳רי באטלר, מקבל כאן ביצוע מלא אנרגיה.''',
'''באותם ימי הקלטה נולד גם Suspicious Minds, שיצא כסינגל נפרד והפך ללהיט הגדול האחרון של אלביס במקום הראשון באמריקה. האלבום עצמו הראה שהזמר של שנות החמישים יכול להיות אמן בוגר ורלוונטי, והמבקרים רואים בו עד היום את השיא של הקריירה המאוחרת שלו. הוא גם פתח את השלב הבא: חזרה להופעות חיות, בעיקר בלאס וגאס.''',
'''שמעו את האלבום אחרי Dusty in Memphis (אלבום 150): אותה עיר, אותה שנה ואותו עולם של נגני אולפן דרומיים, אבל שני זמרים שונים מאוד שמחפשים בממפיס קול חדש.''',
], [
('In the Ghetto', 'שיר על מעגל העוני בשכונה עירונית, שאלביס שר בשקט וברצינות. אחד השירים הכי אישיים שלו.'),
('Long Black Limousine', 'סיפור קודר על חלומות גדולים שנגמרים בלוויה, עם שירה מלאת רגש.'),
('Only the Strong Survive', 'סול קצבי עם כלי נשיפה וזמרות ליווי, ואלביס נשמע משוחרר ונהנה.'),
])

add(152, [
'''אחרי שני אלבומים רועשים ומאתגרים (אלבומים 91 ו־104), הוולווט אנדרגראונד השתנו. ג׳ון קייל, הוויולן והרוח הניסיונית של הלהקה, נאלץ לעזוב, ובמקומו הצטרף דאג יול, נגן בס צעיר ונעים. לו ריד כתב שירים חדשים, שקטים וחשופים, והלהקה הקליטה אותם בלוס אנג׳לס בסוף 1968. האלבום השלישי, שנקרא פשוט בשם הלהקה, יצא ב־1969, ושוב כמעט לא נמכר.''',
'''זה אלבום רך ואינטימי, כמעט עדין: גיטרות נקיות, שירה קרובה למיקרופון, תופים של מורין טאקר שמנגנת בפשטות. Candy Says, ששר דאג יול בקול שביר, הוא דיוקן של אישה טרנסית מהחוג של אנדי וורהול שלא אוהבת את גופה. Pale Blue Eyes הוא שיר אהבה עצוב ויפהפה, ו־Jesus הוא תפילה שקטה. יש גם רגעים קצביים, כמו What Goes On ו־Beginning to See the Light, והאלבום נחתם ב־After Hours, שיר קטן ומתוק שמורין טאקר שרה בעצמה. לו ריד סיפר שהאלבום הוקלט בצורה פשוטה מאוד, כמעט כמו חזרה, כדי שהשירים יישמעו קרובים ואמיתיים.''',
'''אחרי הרעש, הוולווט הוכיחו שהם יכולים להיות גם עדינים בלי לאבד את הכנות ואת הזוויות החדות של לו ריד. האלבום השפיע מאוד על אינדי ופולק־רוק שקט של השנים הבאות, מלהקות כמו R.E.M. ועד מוזיקאים שמנגנים בחדרי שינה. שירים כמו Pale Blue Eyes ו־Candy Says זכו מאז לעשרות גרסאות כיסוי.''',
'''שמעו את Sister Ray באלבום 104 ומיד אחריו את Candy Says: אותה להקה, שנה אחת בהפרש, ונדמה שעברו עשר שנים. זה אלבום טוב לשעות הלילה המאוחרות, בשקט ובאוזניות.''',
], [
('Candy Says', 'הפותח, בקולו השביר של דאג יול: דיוקן עצוב ורך של מישהי שרוצה להיות מישהי אחרת.'),
('Pale Blue Eyes', 'שיר אהבה שקט ומכאיב על אהבה אסורה, מהיפים שכתב לו ריד.'),
('What Goes On', 'הרגע הקצבי של האלבום, עם אורגן מזמזם וגיטרות שחוזרות על עצמן בהנאה.'),
])

add(153, [
'''קוויקסילבר מסנג׳ר סרוויס היו מהלהקות הראשונות של סצנת סן פרנסיסקו, לצד גרייטפול דד וג׳פרסון איירפליין (אלבום 96), אבל הם לא מיהרו לחתום בחברת תקליטים. הכוח שלהם היה על הבמה, בעיקר בזכות שני גיטריסטים: ג׳ון צ׳יפולינה, עם צליל רוטט ומבריק שאין לו מקבילה, וגארי דאנקן. Happy Trails, האלבום השני שלהם, יצא ב־1969 ונבנה בעיקר מהקלטות הופעה באולמות הפילמור של ביל גרהאם.''',
'''צד אחד שלם הוא סוויטה ארוכה סביב Who Do You Love, רוקנרול ישן של בו דידלי: הלהקה לוקחת את המקצב הפשוט ומותחת אותו לחלקים, כשכל נגן מקבל חלק משלו לאלתר, והקהל מוחא כפיים ומשתתף. זה נשמע כמו ג׳אם פתוח, אבל עם מבנה ברור. אחריו מגיעה Mona, עוד שיר של בו דידלי, ו־Calvary, יצירה ארוכה ואפלה שהוקלטה באולפן, עם גיטרות ספרדיות ואווירה של מערבון.''',
'''זה אחד התיעודים הטובים ביותר של מה שקרה באמת באולמות של סן פרנסיסקו בסוף שנות השישים: לא שירי שלוש דקות אלא מסע משותף של להקה וקהל. הגיטרה של צ׳יפולינה השפיעה על גיטריסטים רבים, והאלבום נחשב לאחד מאלבומי ההופעה הגדולים של התקופה. צ׳יפולינה ניגן עם מגברים שבנה והרכיב בעצמו, והצליל הרוטט שלו, שנשמע כמעט כמו מנדולינה חשמלית, הוא סימן ההיכר של הלהקה.''',
'''שמעו את Who Do You Love בגרסה המקורית של בו דידלי ואז את הסוויטה כאן, או השוו לגרייטפול דד באלבום 165 מאותה שנה, שגם הם מתחו שירים בהופעה, בכיוון אחר לגמרי.''',
], [
('Who Do You Love, Pt. 1', 'פתיחת הסוויטה: המקצב של בו דידלי, גיטרות רוטטות וקהל שמוחא כפיים.'),
('Mona', 'עוד שיר של בו דידלי, עם תיפוף מהפנט וגיטרות שמתפתלות סביבו.'),
('Calvary', 'יצירה ארוכה ואפלה עם ניחוח של מערבון: הצד האולפני והקולנועי של הלהקה.'),
])

add(154, [
'''כשהיארדבירדס התפרקו ב־1968, הגיטריסט ג׳ימי פייג׳, שהיה קודם נגן אולפן מבוקש בלונדון, הקים להקה חדשה: הזמר רוברט פלאנט והמתופף ג׳ון בונהאם, שני צעירים ממרכז אנגליה, ונגן הבס והקלידים ג׳ון פול ג׳ונס, גם הוא ותיק אולפנים. אחרי סיבוב הופעות קצר בסקנדינביה הם נכנסו לאולפן בלונדון והקליטו את אלבום הבכורה במהירות, בתוך ימים ספורים. הוא יצא בתחילת 1969. פייג׳ שילם בעצמו על ההקלטות, וכך שמר לעצמו שליטה מלאה על הצליל, דבר נדיר מאוד אצל להקה חדשה.''',
'''הבסיס הוא בלוז, אבל מנוגן בעוצמה ובנפח שלא נשמעו קודם: התופים של בונהאם גדולים ורועמים, הגיטרה של פייג׳ כבדה ומלאת רעיונות, והקול של פלאנט צורח ומתחנן. Good Times Bad Times פותח בקצב מהיר ומפתיע, Dazed and Confused הוא יצירה אפלה וארוכה שבה פייג׳ מנגן על הגיטרה בקשת של כינור, ו־Communication Breakdown הוא פרץ קצר ורעשני. באמצע יש גם רגעים אקוסטיים, כמו Babe I'm Gonna Leave You ו־Black Mountain Side, שמראים את האהבה של פייג׳ לפולק הבריטי.''',
'''המבקרים לא התלהבו בהתחלה, אבל הקהל כן, והאלבום הפך את לד זפלין לאחת הלהקות הגדולות בעולם כמעט מיד. יחד עם אלבום 156 שיצא באותה שנה הוא הניח את היסודות של הארד רוק ושל ההבי מטאל. ברבות השנים התברר שחלק מהשירים נשענו על שירי בלוז ופולק קיימים בלי קרדיט מספיק, וחלק מהקרדיטים תוקנו מאוחר יותר.''',
'''שמעו את You Shook Me כאן ואז את הגרסה של ג׳ף בק, שיצאה שנה קודם עם רוד סטיוארט כזמר: אותו שיר בלוז, ושתי דרכים להפוך אותו לרוק כבד.''',
], [
('Good Times Bad Times', 'הפתיחה: קצב מהיר, גיטרה חדה ותופים שנשמעים כמו סערה. כרטיס ביקור מושלם.'),
('Dazed and Confused', 'יצירה אפלה ומהפנטת, עם קטע שבו פייג׳ מנגן על הגיטרה בקשת.'),
("Babe I'm Gonna Leave You", 'מעבר מדהים בין גיטרה אקוסטית שקטה לפרצי עוצמה: השילוב שיהפוך לסימן ההיכר של הלהקה.'),
])

add(155, [
'''אחרי אלבום הבכורה Music From Big Pink (אלבום 127), הלהקה שליוותה את בוב דילן רצתה להקליט אלבום שני בתנאים משלה. הם שכרו בית בהוליווד, שהיה שייך לפי הסיפור לסמי דייוויס ג׳וניור, והפכו את בית הבריכה שלו לאולפן. שם, בתחילת 1969, הם הקליטו את האלבום שנקרא פשוט The Band, והמעריצים קוראים לו "האלבום החום" בגלל העטיפה.''',
'''השירים נשמעים כאילו נכתבו לפני מאה שנה, אף שכמעט כולם חדשים: סיפורים על איכרים, על מלחמת האזרחים, על קציר ועל חובות. רובי רוברטסון כתב את רובם, ושלושה זמרים שונים מחליפים ביניהם את השירה: ליבון הלם עם קול דרומי מחוספס, ריצ׳רד מנואל עם קול שביר ורגשי, וריק דנקו. The Night They Drove Old Dixie Down מסופר מפיו של חקלאי מהדרום המובס, Up on Cripple Creek הוא שיר עליז עם קלביננט מקפץ, ו־King Harvest מספר על חקלאי שמצטרף לאיגוד מקצועי. רובי רוברטסון כתב את רוב השירים, אבל שלושה זמרים שונים, ריצ׳רד מנואל, ריק דנקו וליבון הלם, חולקים את השירה, וכל אחד מביא צבע אחר.''',
'''בזמן שהרוק של 1969 היה רועש ופסיכדלי, האלבום הזה פנה לאחור, אל שורשים של קאנטרי, פולק, גוספל ובלוז, והפך אותם לדבר חדש. הוא נחשב לאחד האלבומים החשובים בתולדות מה שנקרא היום "אמריקנה", והשפיע על קלפטון, על ג׳ורג׳ הריסון ועל דורות של מוזיקאים. הלהקה אף הופיעה על שער המגזין "טיים" בזכותו.''',
'''זה אלבום שכדאי לשמוע ברצף, כמו אוסף סיפורים קצרים. שימו לב איך הזמרים מעבירים את השירה ביניהם באמצע השיר, ואיך כל כלי מקבל מקום בלי שאף אחד ידחוף לקדמת הבמה.''',
], [
('The Night They Drove Old Dixie Down', 'שיר על סוף מלחמת האזרחים מנקודת מבט של חקלאי מהדרום, בקולו של ליבון הלם.'),
('Up on Cripple Creek', 'שיר עליז ושובב, עם הקלביננט המקפץ של גארת׳ הדסון.'),
('King Harvest (Has Surely Come)', 'שיר הסיום: חקלאי מיואש שמחפש תקווה באיגוד, עם גרוב איטי ומדויק.'),
])

add(156, [
'''לד זפלין הקליטו את האלבום השני שלהם תוך כדי סיבובי הופעות בלתי פוסקים ב־1969: קצת באולפן בלונדון, קצת בלוס אנג׳לס, קצת בניו יורק ואפילו באולפנים קטנים בדרכים. למרות זאת, או אולי בגלל זה, התוצאה נשמעת אחידה, בטוחה ורועמת. האלבום יצא באוקטובר, תשעה חודשים בלבד אחרי הקודם (אלבום 154), ובתוך זמן קצר הגיע למקום הראשון באמריקה ובבריטניה. חלק מהשירים נכתבו בחדרי מלון ובבדיקות סאונד לפני הופעות, ופייג׳ נשא איתו את סרטי ההקלטה מעיר לעיר.''',
'''Whole Lotta Love פותח עם ריף גיטרה שכל מי שניגן אי פעם גיטרה חשמלית מכיר, ובאמצע נפתח לקטע מוזר ומפחיד של רעשים והדהודים שעוברים בין הרמקולים. Heartbreaker כולל סולו גיטרה בלי ליווי שהפך לאגדה, Moby Dick הוא הבמה של ג׳ון בונהאם לסולו תופים, ו־Ramble On משלב גיטרות אקוסטיות וטקסט שמושפע מ"שר הטבעות". יש גם שירי בלוז כבדים, ו־Thank You, שיר אהבה רך שפלאנט כתב לאשתו.''',
'''יותר מכל אלבום אחר, זה האלבום שהגדיר את הצליל של הרוק הכבד בשנות השבעים: הריפים, התופים הגדולים והשירה הגבוהה והצורחת. גם כאן, כמו באלבום הראשון, חלק מהשירים נשענו על שירי בלוז ישנים, ולאחר תביעות התווספו לקרדיטים שמות כמו וילי דיקסון. האלבום נמכר במיליונים, והפך את הלהקה לגדולה בעולם.''',
'''שמעו את Whole Lotta Love באוזניות, כדי לשמוע את הקטע האמצעי זז משמאל לימין, ואחר כך את Thank You: אותה להקה, באותו אלבום, בשני קצוות.''',
], [
('Whole Lotta Love', 'הריף המפורסם, והקטע האמצעי הפסיכדלי שזז בין הרמקולים ומפחיד קצת.'),
('Heartbreaker', 'רוק כבד ומתפוצץ, עם סולו גיטרה בודד שכל גיטריסט צעיר ניסה ללמוד.'),
('Ramble On', 'גיטרות אקוסטיות שהופכות לרוק מלא, וטקסט על מסע בהשראת טולקין.'),
])

add(157, [
'''ה־MC5 הגיעו מדטרויט, עיר של מפעלי מכוניות ושל מוטאון, ובסוף שנות השישים הם היו הלהקה הכי רועשת ופוליטית בעיר. המנהל שלהם, המשורר והפעיל הרדיקלי ג׳ון סינקלר, ראה בהם כלי למהפכה. חברת Elektra החתימה אותם, והחליטה להקליט את אלבום הבכורה בהופעה חיה, כי שם הם היו במיטבם: באולם Grande Ballroom בדטרויט, בערבים של אוקטובר 1968. האלבום יצא בתחילת 1969.''',
'''מהשנייה הראשונה זה נשמע כמו הופעה שיוצאת משליטה: שני גיטריסטים, וויין קריימר ופרד "סוניק" סמית׳, מנגנים חזק ומהר, והזמר רוב טיינר צועק כמו מטיף. שיר הנושא, Kick Out the Jams, הוא קריאה להתפרע, ו־Ramblin' Rose פותח בשירה גבוהה ומפתיעה של קריימר. בהמשך מגיע Motor City Is Burning, על מהומות 1967 בעיר, והאלבום נסגר ב־Starship, ג׳אם חללי וכאוטי בהשראת המוזיקאי הג׳אזי סאן רא.''',
'''המילה הגסה שבפתיחת שיר הנושא גרמה לשערורייה: חנויות סירבו למכור את האלבום, והלהקה נכנסה לריב פומבי עם רשת חנויות גדולה, מה שעלה לה בחוזה עם Elektra. אבל האנרגיה הגולמית, הפוליטיקה והרעש הפכו את האלבום לאב קדמון של הפאנק, יחד עם הסטוג׳ס (אלבומים 171 ו־199), שהגיעו מאותה סצנה ומאותה חברת תקליטים. שנים אחר כך, להקות פאנק רבות ביצעו את Kick Out the Jams, והצעקה שבפתיחתו הפכה לאחד הרגעים המוכרים ברוקנרול.''',
'''זה אלבום שצריך לשמוע בקול רם. אל תחפשו בו דיוק או שירה נקייה: הוא מתעד לילה של להקה וקהל שמזינים זה את זה, ולכן הוא נשמע כמו אירוע ולא כמו הקלטה.''',
], [
('Kick Out the Jams', 'שיר הנושא: שתי דקות וחצי של גיטרות וצעקות, והפתיחה המפורסמת שגרמה לשערורייה.'),
("Ramblin' Rose", 'הפותח: שיר ישן שמתחיל בשירה גבוהה ומתפוצץ לרוקנרול פרוע.'),
('Motor City Is Burning', 'בלוז כבד ומאיים על המהומות בדטרויט, עם טקסט פוליטי ישיר.'),
])

add(158, [
'''הטמפטיישנס היו אחת מלהקות הקול הגדולות של מוטאון, עם הרמוניות מושלמות, חליפות תואמות וצעדי ריקוד מדויקים. אבל ב־1968 הזמר הראשי דייוויד רפין עזב, ובמקומו הגיע דניס אדוארדס, עם קול מחוספס וגוספלי יותר. באותה תקופה המפיק נורמן וויטפילד שמע את סליי והפמילי סטון (אלבום 159) והחליט שגם מוטאון צריכה להישמע אחרת: קצבים ארוכים, גיטרות עם וואה־וואה, אפקטים פסיכדליים ומילים על הרחוב.''',
'''שיר הנושא, Cloud Nine, מתאר צעיר שבורח מהעוני ומהמצוקה אל עננים של סמים, וההרמוניות עוברות בין הזמרים מעל גרוב פאנקי ומבעבע. Runaway Child, Running Wild הוא יצירה של יותר מתשע דקות על ילד שברח מהבית ומחפש את אמו ברחובות, עם קטע אינסטרומנטלי ארוך. באלבום יש גם גרסה של הטמפטיישנס ל־I Heard It Through the Grapevine, השיר שוויטפילד כתב עם בארט סטרונג ושהפך ללהיט ענק בביצוע של מרווין גיי.''',
'''Cloud Nine זכה בפרס גראמי, הראשון של מוטאון, והאלבום פתח את התקופה של "סול פסיכדלי" בחברה: שירים ארוכים, חברתיים ואפלים יותר, שהגיעו לשיא בלהיטים כמו Papa Was a Rollin' Stone. הוא הוכיח שגם במוטאון, מפעל הלהיטים המסודר, אפשר לנסות דברים חדשים ולדבר על מה שקורה בחוץ. הזמרים עצמם לא תמיד אהבו את הכיוון החדש, וחלקם העדיפו את שירי האהבה הישנים, אבל ההצלחה נתנה לוויטפילד חופש להמשיך.''',
'''שמעו את Cloud Nine מיד אחרי Stand! של סליי והפמילי סטון (אלבום 159): תשמעו בדיוק את ההשפעה, ואיך מוטאון לקחה אותה והלבישה אותה בהרמוניות של להקת קולות.''',
], [
('Cloud Nine', 'שיר הנושא: גרוב פאנקי, קולות מתחלפים וטקסט על בריחה מהמציאות.'),
('Runaway Child, Running Wild', 'יותר מתשע דקות של סיפור על ילד אבוד ברחובות, עם קטע אינסטרומנטלי מתוח.'),
('I Heard It Through the Grapevine', 'השיר המפורסם בגרסה של להקת קולות: אותו סיפור קנאה, מזווית אחרת.'),
])

add(159, [
'''סליי סטון היה תקליטן רדיו ומפיק צעיר בסן פרנסיסקו לפני שהקים להקה שנראתה אז כמו חלום: שחורים ולבנים, גברים ונשים, מנגנים יחד סול, רוק ופאנק. בלהקה היו אחיו פרדי, אחותו רוז, החצוצרנית סינתיה רובינסון, והבסיסט לארי גרהאם, שהמציא כמעט לבד את צליל הבס "המוקש" של הפאנק. Stand!, האלבום הרביעי שלהם, יצא באביב 1969, כמה חודשים לפני ההופעה הבלתי נשכחת שלהם בוודסטוק.''',
'''כמעט כל שיר כאן הוא המנון: Stand! קורא לעמוד על שלך, Everyday People מזכיר שכולנו אנשים רגילים ושאין סיבה לשנוא, ו־I Want to Take You Higher הוא פיצוץ של אנרגיה שהקהל צועק יחד איתו. אבל יש גם צד מר יותר: שיר אחד עם שם פרובוקטיבי במיוחד עוסק בגזענות ישירות, ו־Sex Machine הוא ג׳אם של יותר מ־13 דקות, כמעט בלי מילים, שבו סליי משחק עם אפקטים מעוותים על הקול ועל הכלים. הקולות של כל חברי הלהקה מתחלפים על המיקרופון, גברים ונשים, וכך כל שיר נשמע כמו מסיבה שכולם מוזמנים אליה.''',
'''Everyday People הגיע למקום הראשון באמריקה, והאלבום נמכר במיליונים. ההשפעה שלו עצומה: הוא שינה את מוטאון (אלבום 158), השפיע על מיילס דייוויס, על ג׳יימס בראון, על פרינס ועל ההיפ הופ, שדגם ממנו שוב ושוב. יותר מזה, הוא הציע מודל של להקה מעורבת ואופטימית בשנה מתוחה מאוד בחברה האמריקאית.''',
'''התחילו ב־Everyday People ו־I Want to Take You Higher, שני השירים שמסכמים את הרוח של הלהקה. אחר כך הקשיבו ל־Sex Machine כמו לג׳אז: כל נגן מקבל מקום לאלתר, והבס של לארי גרהאם מחזיק את הכול.''',
], [
('Everyday People', 'המנון פשוט ומדבק נגד שנאה, עם השורה "different strokes for different folks". מקום ראשון במצעד.'),
('I Want to Take You Higher', 'פיצוץ של אנרגיה, קריאות ושאגות: השיר שהרים את וודסטוק על הרגליים.'),
('Stand!', 'שיר הנושא: קריאה לעמוד על שלך, שמסתיימת בפתאומיות בגרוב גוספל שמח.'),
])

add(160, [
'''טים באקלי התחיל כזמר פולק צעיר ויפה תואר עם קול עצום בטווח שלו (אלבום 86). אבל בסוף שנות השישים הוא התעניין פחות בשירי פולק מסודרים ויותר בג׳אז, בעיקר במיילס דייוויס (אלבום 145). ב־Happy Sad, האלבום השלישי שלו, שיצא ב־1969, הוא ויתר על התזמורים ועל ההפקה העשירה של האלבום הקודם, ובחר בהרכב קטן: גיטרה, קונטרבס, קונגה, ויברפון ותו לא. השם, "שמח עצוב", מתאר בדיוק את מצב הרוח של השירים: אהבה מאושרת שיש בה תמיד משהו נוגה.''',
'''השירים ארוכים, פתוחים ורגועים, והנגנים מקשיבים זה לזה כמו בהרכב ג׳אז. הוויברפון של דייוויד פרידמן מוסיף צלילים מנצנצים, הבס זז בחופשיות, והקול של באקלי נע בין לחישה לצעקה, לפעמים בתוך אותה שורה. Strange Feelin' פותח בגרוב שקט שמזכיר את מיילס, Love from Room 109 at the Islander הוא שיר של כמעט 11 דקות, עם קול גלי הים ברקע, על אהבה שנמצאת ואובדת, ו־Buzzin' Fly הוא שיר אהבה קליל ושמח.''',
'''Happy Sad היה האלבום של באקלי שהגיע למקום הגבוה ביותר במצעד האמריקאי, אבל זו הייתה הצלחה צנועה. מכאן הוא המשיך רחוק יותר, לג׳אז חופשי ולניסויים קוליים שאיבדו לו את רוב הקהל. היום הוא נחשב לאחד הקולות הגדולים של התקופה, ובנו ג׳ף באקלי המשיך את הדרך בשנות התשעים.''',
'''שמעו את האלבום בשעת ערב, בלי הסחות דעת. השוו את Buzzin' Fly לשירים של Goodbye and Hello (אלבום 86): הקול אותו קול, אבל המוזיקה נושמת ונפתחת.''',
], [
("Strange Feelin'", 'הפותח: גרוב שקט של בס וויברפון, וקול שמתרומם לאט.'),
("Buzzin' Fly", 'שיר אהבה קליל ומאושר, הרגע הכי "שמח" באלבום, עם ויברפון מנצנץ.'),
('Love from Room 109 at the Islander (On Pacific Coast Highway)', 'שיר ארוך וחלומי עם גלי ים ברקע, על אהבה בחדר מלון ליד החוף.'),
])

add(161, [
'''שבעה מוזיקאים צעירים משיקגו, רובם סטודנטים למוזיקה, רצו לשלב רוק עם כלי נשיפה של ג׳אז: חצוצרה, טרומבון וסקסופון, לצד גיטרה, בס, קלידים ותופים. הם קראו לעצמם על שם חברת התחבורה הציבורית של העיר, Chicago Transit Authority, ועברו ללוס אנג׳לס עם המפיק והמנהל ג׳יימס ויליאם גרסיו. אלבום הבכורה שלהם יצא ב־1969, והיה אלבום כפול, מהלך נועז ללהקה שאף אחד עוד לא הכיר.''',
'''כלי הנשיפה לא רק מלווים, הם מנגנים מלודיות חדות ומדויקות כמו בלהקת ביג בנד. Does Anybody Really Know What Time It Is? נפתח במבוא פסנתר חופשי ואז הופך לשיר פופ שמח על הזמן שבורח, Beginnings הוא שיר אהבה קליל עם גיטרות אקוסטיות וסיום ארוך של כלי הקשה, ו־I'm a Man הוא גרסה סוערת ללהיט של Spencer Davis Group. הגיטריסט טרי קאת׳ מקבל כאן במה רחבה, כולל קטע שלם של רעש ופידבק חופשי.''',
'''מהאלבום הזה יצאו כמה להיטים, והלהקה, שקיצרה זמן קצר אחר כך את שמה ל־Chicago אחרי שחברת התחבורה איימה בתביעה, הפכה לאחת הלהקות המצליחות באמריקה בשנות השבעים. יחד עם Blood, Sweat & Tears הם הפכו את "רוק עם כלי נשיפה" לז׳אנר של ממש. טרי קאת׳, גיטריסט מוערך מאוד, מת בתאונה ב־1978, והלהקה המשיכה בכיוון רך ופופי יותר.''',
'''התחילו ב־Beginnings ו־Does Anybody Really Know What Time It Is?, שני השירים הכי מוכרים. אם אתם אוהבים גיטרה, שמעו אחר כך את Free Form Guitar, ניסוי קיצוני של קאת׳ שנשמע היום כמעט כמו רוק ניסיוני מאוחר בהרבה.''',
], [
('Does Anybody Really Know What Time It Is?', 'מבוא פסנתר חופשי שנפתח לשיר פופ עליז על הזמן שבורח, עם כלי נשיפה חדים.'),
('Beginnings', 'שיר אהבה קליל וחם, שמסתיים בחגיגה ארוכה של כלי הקשה.'),
("I'm a Man", 'גרסה סוערת ללהיט של Spencer Davis Group, עם תופים ואורגן בוערים.'),
])

add(162, [
'''פיירפורט קונבנשן התחילו כלהקה בריטית שניגנה שירים של דילן, של ג׳וני מיצ׳ל ושל כותבים אמריקאים, והייתה מכונה "ג׳פרסון איירפליין הבריטית". ב־1968 הצטרפה אליה הזמרת סנדי דני, עם קול צלול ועמוק ועם שירים משלה, והלהקה התחילה להתעניין בשירי עם בריטיים עתיקים. Unhalfbricking, האלבום השלישי שלהם, יצא באמצע 1969. על העטיפה נראים הוריה של סנדי דני מול ביתם בלונדון, והלהקה מופיעה רק ברקע.''',
'''האלבום עומד על קו התפר: שלושה שירים של דילן, אחד מהם בצרפתית, Si Tu Dois Partir, שהפך ללהיט קטן בבריטניה; שירים של חברי הלהקה; ו־A Sailor's Life, שיר עם עתיק על נערה שמחפשת את אהובה שטבע בים, שהלהקה מותחת ל־11 דקות של אלתור עם הכנר דייב סווורבריק. וגם Who Knows Where the Time Goes?, שיר שסנדי דני כתבה כנערה על חלוף הזמן, אחד השירים היפים ביותר בפולק הבריטי. ריצ׳רד תומפסון, אז רק בן עשרים, כבר מנגן כאן בגיטרה בסגנון אישי מאוד, שבו אפשר לשמוע גם רוק וגם מוזיקה עממית ישנה.''',
'''כחודשיים לפני יציאת האלבום, במאי 1969, הרכב הלהקה התהפך בדרך חזרה מהופעה. המתופף מרטין למבל, בן 19, ובת הזוג של הגיטריסט ריצ׳רד תומפסון נהרגו. הלהקה כמעט התפרקה, ובמקום זאת בנתה את עצמה מחדש סביב שירי עם בריטיים, כפי שנשמע באלבום 169 שיצא באותה שנה. A Sailor's Life הוא הרגע שבו הכיוון הזה נולד.''',
'''שמעו את A Sailor's Life ואחריו את Matty Groves מאלבום 169: תשמעו איך ניסוי חד־פעמי הפך בתוך חודשים ספורים לסגנון חדש, "פולק רוק בריטי".''',
], [
('Who Knows Where the Time Goes?', 'השיר המפורסם של סנדי דני על חלוף הזמן, בשירה רגועה ומרגשת.'),
("A Sailor's Life", 'שיר עם עתיק שהופך למסע של 11 דקות, עם כינור, גיטרה חשמלית ותופים.'),
('Si Tu Dois Partir', 'שיר של דילן בצרפתית, בגרסה עליזה של מסיבה, עם אקורדיון וכלי הקשה מאולתרים.'),
])

add(163, [
'''היאנגבלאדס זכורים בעיקר בזכות Get Together, המנון השלום והאחווה ששרו כבר ב־1967 והפך ללהיט רק שנתיים מאוחר יותר. בינתיים הם עזבו את ניו יורק ועברו לצפון קליפורניה, לאזור השקט של מחוז מרין, ושם הקליטו את Elephant Mountain, האלבום השלישי שלהם, שיצא ב־1969. באמצע העבודה עזב אחד החברים, ונשארו שלושה: הזמר והבסיסט ג׳סי קולין יאנג, לואל "בננה" לוינגר על גיטרה וקלידים, והמתופף ג׳ו באואר.''',
'''זה אלבום רגוע, כפרי וקצת ג׳אזי, עם הרבה אוויר בין הכלים. Darkness, Darkness, השיר הפותח, הוא תפילה קודרת ויפהפייה עם כינור מייבב, שנשמעת כמו שיר על פחד ועל חושך פנימי. Sunlight הוא שיר אהבה רך ושקט, ויש גם קטעים אינסטרומנטליים קצרים, שירים קלילים עם ניחוח של קאנטרי, ורגעים של ג׳אם ג׳אזי. הקול של ג׳סי קולין יאנג חם ורך, כמו יום חורפי מול האח.''',
'''Elephant Mountain לא היה להיט גדול, אבל הוא נחשב לאלבום הטוב של הלהקה ולאחת הדוגמאות היפות לרוק הכפרי והרגוע של צפון קליפורניה בסוף שנות השישים. Darkness, Darkness זכה לגרסאות רבות לאורך השנים, והפך לשיר מוכר יותר מהלהקה עצמה. באותן שנים היאנגבלאדס היו חלק מהסצנה של סן פרנסיסקו, והופיעו לצד להקות גדולות מהם, אבל תמיד שמרו על צליל שקט ועדין משלהן.''',
'''זה אלבום טוב לבוקר שקט או לנסיעה ארוכה. אחרי Darkness, Darkness, שמעו את Get Together, הלהיט הגדול שלהם שאינו באלבום, כדי להכיר את הצד האופטימי של הלהקה.''',
], [
('Darkness, Darkness', 'הפותח: תפילה קודרת ויפהפייה, עם כינור מייבב וקול שמבקש אור.'),
('Sunlight', 'שיר אהבה רך ושקט, כמו קרן שמש שנכנסת לחדר בבוקר חורפי.'),
('Ride the Wind', 'שיר ארוך ורגוע שנפתח לג׳אם עם ניחוח ג׳אזי, כמו נסיעה בדרך פתוחה.'),
])

add(164, [
'''אייזק הייז היה פסנתרן, כותב ומפיק בחברת Stax בממפיס, ויחד עם דייוויד פורטר כתב שם להיטים כמו Soul Man. ב־1968 Stax איבדה את הקטלוג שלה והייתה צריכה לייצר במהירות עשרות אלבומים חדשים. הייז קיבל חופש מלא להקליט מה שהוא רוצה, והוא ניצל אותו עד הסוף: Hot Buttered Soul, שיצא ב־1969, כולל ארבעה שירים בלבד, ושניים מהם ארוכים יותר מעשר דקות.''',
'''הוא לוקח שירי פופ מוכרים ומותח אותם לסוויטות סול עצומות. Walk On By, השיר של ברט בכרך, נמשך יותר מ־12 דקות, עם כלי מיתר מלאים, גיטרה חשמלית מייללת וקצב איטי וכבד. By the Time I Get to Phoenix, להיט קאנטרי של ג׳ימי ווב, נפתח בנאום של יותר משמונה דקות: הייז מספר, מעל אורגן שקט, את סיפורו של הגבר שעוזב את אשתו, לפני שהוא מתחיל לשיר. והקול: עמוק, נמוך, סמכותי ורך.''',
'''האלבום היה הצלחה ענקית ומפתיעה ושינה את המוזיקה השחורה: הוא הוכיח שאלבום סול יכול להיות יצירה ארוכה ושאפתנית ולא רק אוסף של סינגלים. הצליל שלו, עם כלי מיתר מפוארים, בס עמוק ודיבור מעל המוזיקה, הוביל לסול של שנות השבעים, לפסקול של Shaft שהייז כתב שנתיים אחר כך, ולהיפ הופ, שדגם ממנו בלי סוף.''',
'''זה אלבום שכדאי לשמוע בשקט, ברצף, בלי למהר. תנו ל־By the Time I Get to Phoenix את כל 18 הדקות שלו: הדיבור בתחילתו הוא חלק מהקסם, והשירה, כשהיא מגיעה סוף סוף, נשמעת כמו שחרור.''',
], [
('Walk On By', 'שיר של ברט בכרך שהופך ל־12 דקות של סול מפואר, איטי ודרמטי.'),
('By the Time I Get to Phoenix', '18 דקות: נאום ארוך ומהפנט מעל אורגן, ואז שירה שקטה ושבורה.'),
('One Woman', 'השיר הקצר באלבום: בלדת סול יפה על גבר שקרוע בין שתי נשים.'),
])

add(165, [
'''גרייטפול דד היו הלהקה הכי מזוהה עם סן פרנסיסקו של שנות השישים, והקהל שלהם ידע שהם במיטבם על הבמה: כל הופעה הייתה שונה, והשירים נמתחו לאלתורים ארוכים. באלבומי האולפן הראשונים שלהם הם התקשו ללכוד את הקסם הזה. Live/Dead, שיצא בסוף 1969, הוא הפתרון: הקלטות מהופעות בתחילת אותה שנה באולמות Fillmore West ו־Avalon, עם ציוד הקלטה מתקדם לתקופתו.''',
'''הצד הראשון כולו הוא Dark Star, אלתור של יותר מעשרים דקות סביב שיר קצר ומסתורי: הגיטרה של ג׳רי גרסיה מרחפת, הבס של פיל לש מנגן מלודיות משלו, שני מתופפים מתפתלים סביבם, והמוזיקה זזה לאט, כמו עננים. ממנה הלהקה עוברת ל־St. Stephen ול־The Eleven, שיר במשקל מוזר של אחד־עשר, ומשם ל־Turn On Your Love Light, שיר סול שבו הזמר רון "פיגפן" מקרנן מלהיב את הקהל. בסוף יש בלוז כבד, רעש ופידבק, ושיר פרידה שקט בהרמוניה.''',
'''Live/Dead נחשב לאחד מאלבומי ההופעה הגדולים של הרוק, ולתיעוד הטוב ביותר של הדד בשיא הפסיכדלי שלהם. הוא עזר להפוך את הלהקה לתופעה של הופעות, עם קהל נאמן שנסע אחריה מעיר לעיר, מסורת שנמשכה עשרות שנים. אחרי האלבום הזה הם פנו לכיוון אחר לגמרי, שקט וכפרי, שנשמע באלבום 189.''',
'''אל תנסו לשמוע את Dark Star כשיר רגיל. הקשיבו לו כמו לג׳אז, וכדאי לעקוב אחרי כלי אחד בכל פעם: הגיטרה, אחר כך הבס, אחר כך התופים. אחר כך השוו ל־American Beauty (אלבום 189): אותה להקה, כמעט הפוכה.''',
], [
('Dark Star', 'יותר מעשרים דקות של אלתור מרחף: הלב של האלבום ושל הלהקה.'),
('St. Stephen', 'שיר קצבי ומלא הרמוניות שנולד מתוך Dark Star, עם הפסקות ודרמה.'),
('Turn On Your Love Light', 'שיר סול שהופך לחגיגה ארוכה, עם פיגפן שמדבר, צועק ומלהיב את הקהל.'),
])

add(166, [
'''ריי דייוויס, הכותב של הקינקס, כתב ב־1969 שירים לדרמה טלוויזיונית בריטית על משפחה רגילה מפרברי לונדון. ההשראה הייתה גיסו ארתור, שהיגר עם משפחתו לאוסטרליה. תוכנית הטלוויזיה לא הופקה בסוף, אבל השירים הפכו לאלבום, שיצא באוקטובר 1969, כמעט באותו זמן שבו The Who הוציאו את אופרת הרוק שלהם (אלבום 144). הקינקס כמעט לא הורשו להופיע באמריקה באותן שנים, בגלל סכסוך עם איגוד המוזיקאים שם, ואולי בגלל זה ריי דייוויס כתב כל כך הרבה על אנגליה.''',
'''האלבום מספר, דרך חייו של ארתור, את סיפורה של בריטניה במאה העשרים: Victoria, השיר הפותח, הוא שיר רוק שמח שמהלל באירוניה את ימי המלכה ויקטוריה, Some Mother's Son הוא שיר עצוב על חיילים צעירים שנהרגים במלחמה, Australia הוא הבטחה לחיים טובים יותר מעבר לים, ו־Shangri-La מתאר גבר שמשיג את הבית הקטן שחלם עליו, ומגלה שהוא כלוא בו. הלחנים מגוונים: רוקנרול, מוזיקת אולמות, בלדות וכלי נשיפה.''',
'''ארתור נמכר מעט, והיה בצל אופרת הרוק של The Who, אבל המבקרים, בעיקר באמריקה, התלהבו, והוא נחשב היום לאחד האלבומים הטובים של הקינקס. יחד עם The Village Green Preservation Society (אלבום 110) הוא מראה את ריי דייוויס כאחד הכותבים החדים והרגישים ביותר על החיים הבריטיים. רבים רואים ב־Shangri-La שיר מופת קטן על מעמד הפועלים הבריטי, ועל הפער בין החלום על בית משלך לבין החיים עצמם.''',
'''שמעו את Shangri-La בתשומת לב: הוא מתחיל כשיר שקט ומתוק, הופך לרוק גדול, ומתחת לכל זה מסתתר עצב גדול על חלומות קטנים. זה שיר שמתגלה מחדש בכל האזנה.''',
], [
('Victoria', 'הפותח: רוקנרול שמח ואירוני על האימפריה הבריטית בימיה הגדולים.'),
('Shangri-La', 'שיר על בית קטן ועל חלום שהפך לכלוב, שנפתח משקט לפיצוץ.'),
("Some Mother's Son", 'שיר שקט ושבור על חיילים צעירים שנהרגים רחוק מהבית.'),
])

add(167, [
'''קינג קרימזון נוצרה בלונדון ב־1968 סביב הגיטריסט רוברט פריפ, שנגן בשקט ובדיוק כמעט מתמטי. איתו היו הזמר והבסיסט גרג לייק, איאן מקדונלד על כלי נשיפה וקלידים, המתופף מייקל ג׳יילס, והמשורר פיט סינפילד, שכתב את המילים והיה אחראי על התאורה. ביולי 1969 הם ניגנו לפני קהל עצום בהופעה החינמית של הרולינג סטונס בהייד פארק, ובאוקטובר יצא אלבום הבכורה שלהם. חברי הלהקה התאמנו בחדר מתחת לבית קפה בלונדון, שעות רבות כל יום, עד שהנגינה המורכבת נשמעה טבעית לגמרי.''',
'''האלבום נפתח ב־21st Century Schizoid Man, מתקפה פרועה של ריפים כבדים, סקסופונים וקול מעוות, עם קטע אינסטרומנטלי מהיר ומסובך באמצע. מיד אחריו מגיע I Talk to the Wind, שיר רך עם חליל. Epitaph ושיר הנושא בנויים על המלוטרון, קלידים שמנגנים הקלטות של כלי מיתר ומקהלות, ונשמעים כמו תזמורת עצובה וענקית. Moonchild נפתח בשיר שקט ומתפרק לאלתור ארוך ושקט מאוד.''',
'''זה אחד האלבומים שהמציאו את "הרוק המתקדם", הפרוגרסיב: שילוב של רוק עם ג׳אז, מוזיקה קלאסית ומילים שאפתניות. הוא השפיע על ג׳נסיס, על יס ועל אינספור להקות. העטיפה, הפנים הצורחות שצייר בארי גודבר, היא אחת המפורסמות ברוק. ההרכב המקורי התפרק כמעט מיד, ופריפ המשיך את הלהקה בהרכבים משתנים במשך עשרות שנים. האלבום הוקלט ונכתב במהירות, והלהקה הפיקה אותו בעצמה אחרי שהמפיק הראשון עזב, ובכל זאת הצליל שלו נשמע גדול ומוקפד.''',
'''התחילו ב־21st Century Schizoid Man בקול רם, ומיד אחריו I Talk to the Wind: המעבר החד בין הסערה לשקט הוא כל הרעיון של האלבום.''',
], [
('21st Century Schizoid Man', 'פתיחה פרועה: ריפ כבד, סקסופונים צורחים וקטע אינסטרומנטלי מהיר ומדויק.'),
('Epitaph', 'בלדה עצובה וענקית עם מלוטרון שנשמע כמו תזמורת שלמה.'),
('The Court of the Crimson King', 'שיר הנושא: מלודיה גדולה, מקהלה ודמויות של אגדה אפלה.'),
])

add(168, [
'''אחרי אלבום הבכורה שלו (אלבום 114), לאונרד כהן, המשורר הקנדי שהפך לזמר, נסע לנאשוויל. שם, עם המפיק בוב ג׳ונסטון, שעבד גם עם בוב דילן, הוא הקליט את האלבום השני, Songs From a Room, שיצא ב־1969. ג׳ונסטון החליט להשאיר את השירים כמעט חשופים: גיטרה אקוסטית, קול, ומעט כלים סביבם, כמו נבל יהודי, כינור ועוגב.''',
'''השיר הפותח, Bird on the Wire, כתב כהן באי היווני הידרה, שבו גר באותן שנים. זו תפילה ובקשת סליחה על כל הדרכים שבהן אכזב את מי שאהב, והוא הפך לאחד משיריו המפורסמים ביותר. Story of Isaac מספר מחדש את סיפור עקדת יצחק מנקודת המבט של הילד, והופך אותו לשיר מחאה נגד אבות ששולחים את בניהם למלחמה. The Partisan הוא שיר של מחתרת ההתנגדות הצרפתית במלחמת העולם השנייה, שכהן שר חלקו בצרפתית, עם מקהלה נשית.''',
'''האלבום הגיע למקום השני במצעד הבריטי, וביסס את כהן כאמן שמעניין את הקהל גם אחרי אלבום הבכורה. השירים שלו, שקטים ואינטימיים מאוד, הם דוגמה ללמה כהן נחשב משורר גם כשהוא שר: המילים חשובות כאן לא פחות מהמוזיקה. שירים כמו Bird on the Wire ו־The Partisan הפכו לחלק קבוע מההופעות שלו עד סוף חייו. בין הנגנים היה גם צ׳רלי דניאלס, שהתפרסם אחר כך כזמר קאנטרי, והליווי השקט של כולם משאיר את כל המקום לקול העמוק של כהן.''',
'''זה אלבום לשמוע בשקט ובריכוז, רצוי עם המילים מול העיניים. התחילו ב־Story of Isaac: הסיפור המוכר מהתנ״ך מקבל כאן משמעות חדשה ומטלטלת.''',
], [
('Bird on the Wire', 'הפותח: תפילה ובקשת סליחה, אחד השירים המפורסמים של כהן.'),
('Story of Isaac', 'עקדת יצחק מפי הילד: שיר תנ״כי שהופך לשיר נגד מלחמות.'),
('The Partisan', 'שיר של המחתרת הצרפתית, חציו בצרפתית, עם מקהלת נשים חרישית.'),
])

add(169, [
'''אחרי התאונה במאי 1969 שבה נהרגו המתופף שלהם ובת הזוג של הגיטריסט (אלבום 162), פיירפורט קונבנשן הסתגרו בבית כפרי ישן בדרום אנגליה, עם מתופף חדש, דייב מטאקס, והכנר דייב סווורבריק, שהצטרף כחבר קבוע. שם, במשך כמה שבועות, הם חקרו שירי עם בריטיים עתיקים וחיפשו דרך לנגן אותם כרוק. Liege & Lief יצא בדצמבר 1969.''',
'''רוב האלבום בנוי משירי עם ובלדות מסורתיות, שחלקן בנות מאות שנים: Matty Groves היא בלדה של שמונה דקות על אישה אצילה, מאהב ובעל נוקם, שמסתיימת בקטע אינסטרומנטלי סוער של גיטרה וכינור. Tam Lin מספר על נערה שמצילה את אהובה מידי מלכת הפיות. לצידם יש שירים חדשים שנשמעים עתיקים, כמו Crazy Man Michael ו־Farewell, Farewell. הקול של סנדי דני צלול וחזק, והלהקה מנגנת בכוח של להקת רוק. הכינור של סווורבריק, מהנגנים הגדולים של המוזיקה העממית הבריטית, נותן לשירים חיים ומהירות של ריקודי כפר ישנים.''',
'''Liege & Lief נחשב לאלבום שבו נולד "הפולק רוק הבריטי": הוא הוכיח שהמסורת המקומית יכולה להיות חיה ורלוונטית, בדיוק כמו הבלוז האמריקאי ללהקות הרוק. זמן קצר אחרי יציאתו עזבה סנדי דני כדי להקים להקה משלה, ובסיסט הלהקה, אשלי האצ׳ינגס, עזב והקים את Steeleye Span, שהמשיכה באותו כיוון. שנים רבות אחר כך, מבקרים ומאזינים בחרו בו כאלבום הפולק החשוב ביותר שנעשה בבריטניה.''',
'''התחילו ב־Matty Groves, בלדה שנשמעת כמו סרט מתח מימי הביניים. שימו לב לסיום: הגיטרה של ריצ׳רד תומפסון והכינור של סווורבריק רודפים זה אחר זה, כמו במסיבת ריקודים שיצאה משליטה.''',
], [
('Matty Groves', 'בלדה עתיקה על בגידה ונקמה, עם סיום אינסטרומנטלי סוער.'),
('Tam Lin', 'סיפור אגדה סקוטי על פיות וקסמים, בגרסה חשמלית ודרמטית.'),
('Farewell, Farewell', 'שיר פרידה שקט ויפהפה, שנשמע עתיק אף שהוא חדש.'),
])

add(170, [
'''סקוט ווקר היה כוכב נערות בבריטניה של אמצע שנות השישים עם להקת Walker Brothers, ואז פנה לדרך אישית ומוזרה יותר, עם שירים של ז׳אק ברל ותזמורים גדולים (אלבום 130). Scott 4, שיצא בסוף 1969, היה הצעד הנועז ביותר שלו עד אז: לראשונה כל השירים נכתבו על ידו, והוא הוציא את האלבום בשמו האמיתי, נואל סקוט אנגל, אולי כדי שיישפט על השירים ולא על התדמית.''',
'''השירים עדיין עטופים בכלי מיתר ובתזמורת, אבל הנושאים עמוקים ואפלים: The Seventh Seal פותח בסיפור על אביר ששיחק שחמט עם המוות, בהשראת סרטו של אינגמר ברגמן, עם גיטרות ספרדיות ומקהלה. Hero of the War הוא שיר מחאה עוקצני על חייל ששב הביתה, The Old Man's Back Again עוסק בפלישה הסובייטית לצ׳כוסלובקיה על רקע גרוב של בס, ו־On Your Own Again הוא שיר אהבה שקט ועצוב. הקול העמוק והבריטוני של ווקר נשמע כמו זמר אופרה שהגיע לפופ.''',
'''האלבום נכשל לגמרי: הוא לא נכנס למצעד, והקריירה של ווקר ירדה לתקופה ארוכה של אלבומים מסחריים שהוא עצמו לא אהב. אבל עם השנים Scott 4 התגלה מחדש, ומוזיקאים כמו דייוויד בואי, רדיוהד וג׳ארוויס קוקר הזכירו אותו כהשראה. היום הוא נחשב לאחד מאלבומי הפופ המיוחדים של התקופה.''',
'''שמעו את The Seventh Seal אם ראיתם את סרטו של ברגמן, ואם לא, זו סיבה טובה לראות. ואחר כך השוו ל־Scott 2 (אלבום 130): מזמר של שירים של אחרים לכותב עם עולם שלם משלו.''',
], [
('The Seventh Seal', 'הפותח: סיפור על אביר ששיחק שחמט עם המוות, עם גיטרות ספרדיות ומקהלה.'),
("The Old Man's Back Again", 'גרוב של בס וכלי מיתר, ושיר פוליטי על דיכוי ועל טנקים.'),
('On Your Own Again', 'שיר אהבה קצר, שקט ומכאיב, שבו הקול מרחף מעל התזמורת.'),
])

add(171, [
'''הסטוג׳ס הגיעו מאן ארבור, עיירת אוניברסיטה ליד דטרויט, והזמר שלהם, ג׳יימס אוסטרברג, שקרא לעצמו איגי פופ, היה ידוע בהופעות פרועות שבהן זחל על הבמה, קפץ אל הקהל ופצע את עצמו. האחים רון וסקוט אשטון ניגנו גיטרה ותופים, דייב אלכסנדר ניגן בס. חברת Elektra החתימה אותם יחד עם ה־MC5 (אלבום 157), ובאביב 1969 הם הקליטו בניו יורק את אלבום הבכורה, עם ג׳ון קייל מהוולווט אנדרגראונד (אלבום 91) כמפיק.''',
'''הסטוג׳ס ידעו בקושי לנגן, וזה היה הכוח שלהם: ריפים פשוטים של שניים או שלושה אקורדים, חוזרים שוב ושוב, עם גיטרה מלוכלכת מלאה בוואה־וואה. 1969 פותח בשורה משועממת על עוד שנה שבה אין מה לעשות, I Wanna Be Your Dog בנוי על ריף מאיים, עם פסנתר של תו אחד שקייל הוסיף, ו־No Fun הוא המנון של שעמום. באמצע יש את We Will Fall, מנטרה של עשר דקות עם ויולה של קייל, שנשמעת כמו טקס מוזר.''',
'''האלבום כמעט לא נמכר והמבקרים זלזלו בו, אבל כמה שנים אחר כך הוא הפך לאחד מאבני היסוד של הפאנק. להקות כמו הסקס פיסטולס, הדמנד וסוניק יות׳ ניגנו את השירים שלו, ו־I Wanna Be Your Dog הוא אחד מהשירים שכוסו הכי הרבה ברוק. הוא הוכיח שאנרגיה, גישה וכנות יכולות להיות חשובות יותר מווירטואוזיות.''',
'''שמעו את 1969 ו־I Wanna Be Your Dog בקול רם, ואז את No Fun. אחר כך המשיכו ל־Fun House (אלבום 199), שבו אותה להקה נשמעת כאילו נכנסה ישר לתוך תנור.''',
], [
('1969', 'הפותח: ריף פשוט ומשועמם ושורה על עוד שנה שבה אין מה לעשות. פאנק לפני הפאנק.'),
('I Wanna Be Your Dog', 'ריף מאיים, גיטרה מלוכלכת ופסנתר של תו אחד: אחד השירים המשפיעים ברוק.'),
('No Fun', 'המנון השעמום, שחזר שוב ושוב בגרסאות של להקות פאנק.'),
])

add(172, [
'''סקיפ ספנס ניגן על תופים באלבום הראשון של ג׳פרסון איירפליין והיה גיטריסט וכותב במובי גרייפ (אלבום 81). ב־1968, בזמן הקלטות בניו יורק, הוא התמוטט נפשית, לפי הסיפור אחרי שימוש כבד בסמים, ואושפז לכמה חודשים בבית חולים פסיכיאטרי. ביום שחרורו, כך מספרים, הוא רכב על אופנוע עד נאשוויל, נכנס לאולפן והקליט שם אלבום לבד לגמרי: הוא שר וניגן על כל הכלים. Oar יצא ב־1969.''',
'''זה אלבום מוזר, שבור ויפה: קול עמוק ועייף, גיטרות אקוסטיות פשוטות, תופים בסיסיים, ושירים שנשמעים כאילו הם מתפרקים בזמן שהוא שר אותם. Little Hands, השיר הפותח, הוא שיר תקווה מתוק על ילדים שמחזיקים ידיים בכל העולם. Weighted Down הוא בלוז כבד ואיטי, War in Peace כמעט פסיכדלי, ו־Broken Heart הוא שיר קאנטרי עצוב וחשוף. לפעמים הוא נשמע כמו זמר קאנטרי זקן, ולפעמים כמו מישהו שמדבר לעצמו בחדר ריק.''',
'''לפי מה שמסופר, Oar היה מהאלבומים הכי פחות נמכרים בתולדות חברת Columbia, וספנס נעלם כמעט לגמרי מעולם המוזיקה. אבל האלבום מצא לאט קהל נאמן, ומוזיקאים כמו טום וייטס, בק ורוברט פלאנט השתתפו ב־1999 באלבום מחווה שבו ביצעו את השירים שלו. ספנס מת זמן קצר לפני שיצא. היום Oar נחשב ליצירת מופת של אאוטסיידר, אחד האלבומים האישיים ביותר של התקופה.''',
'''זה לא אלבום לשמוע ברקע. שמעו את Little Hands, ואז את Broken Heart, ותנו לחספוס לעבוד: חלק מהקסם הוא התחושה שאתם שומעים משהו פרטי מאוד.''',
], [
('Little Hands', 'הפותח: שיר תקווה מתוק ופשוט, מלא אהבה לילדים של העולם.'),
('Weighted Down (The Prison Song)', 'בלוז איטי וכבד, עם קול עמוק שנשמע כמו של אסיר זקן.'),
('Broken Heart', 'שיר קאנטרי עצוב, שקט וחשוף, מהרגעים היפים והכנים באלבום.'),
])

add(173, [
'''פרנק זאפה פירק ב־1969 את ה־Mothers of Invention (אלבומים 69 ו־134), הלהקה הסאטירית שלו, והקליט אלבום ראשון בשמו, Hot Rats, שיצא באותה שנה. במקום שירים מצחיקים ופרודיות, הוא הקליט כמעט רק מוזיקה אינסטרומנטלית, שילוב של רוק וג׳אז, עם נגני אולפן מעולים ועם איאן אנדרווד, שניגן על קלידים ועל כלי נשיפה רבים. זה היה גם אחד האלבומים הראשונים שהוקלטו בטכנולוגיה של 16 ערוצים, מה שאפשר לזאפה לבנות שכבות על שכבות.''',
'''Peaches en Regalia פותח עם מנגינה שמחה, מסובכת ומלאת צבעים, עם כלי נשיפה, קלידים ובס, שנשמעת כמו פסקול של סרט מצויר מתוחכם. Willie the Pimp הוא השיר היחיד עם שירה: קפטן ביפהארט (אלבומים 83 ו־136), חבר ילדות של זאפה, שר בקול צרוד וקצר, ואז זאפה יוצא לסולו גיטרה ארוך ובוער. The Gumbo Variations הוא ג׳אם של יותר מ־16 דקות, עם כינור חשמלי של שוגרקיין האריס וסקסופון פרוע.''',
'''Hot Rats היה אחד האלבומים הראשונים של מה שייקרא אחר כך פיוז׳ן, השילוב של רוק וג׳אז, כמה חודשים לפני Bitches Brew של מיילס דייוויס (אלבום 176). הוא הראה שזאפה, שנחשב בעיקר לליצן ולסאטיריקן, הוא גם מלחין רציני וגיטריסט מצוין. Peaches en Regalia הפך לאחד הקטעים המוכרים ביותר שלו, ונוגן על ידי הרכבים רבים.''',
'''התחילו ב־Peaches en Regalia, שלוש וחצי דקות של הנאה טהורה. אחר כך שמעו את Willie the Pimp ושימו לב איך הגיטרה ממשיכה הרבה אחרי שהשירה נגמרת, כמעט כמו סיפור בפני עצמו.''',
], [
('Peaches en Regalia', 'הפותח: מנגינה שמחה, צבעונית ומסובכת, מהיצירות המוכרות של זאפה.'),
('Willie the Pimp', 'קפטן ביפהארט שר בקול צרוד, וזאפה יוצא לסולו גיטרה ארוך ובוער.'),
('The Gumbo Variations', 'ג׳אם ארוך של כינור חשמלי וסקסופון, רוק וג׳אז שמתערבבים עד הסוף.'),
])

add(174, [
'''בשנתיים 1969–1970 קרידנס קלירווטר ריווייבל היו אולי הלהקה המצליחה ביותר באמריקה: הם הוציאו שלושה אלבומים ב־1969 בלבד (בהם אלבומים 137 ו־142) ולהיט אחר להיט. Cosmo's Factory, האלבום החמישי, יצא באמצע 1970 והגיע למקום הראשון. השם לקוח מהמחסן בברקלי שבו הלהקה עשתה חזרות, שהמתופף דאג קליפורד, "קוזמו", כינה "המפעל" בגלל קצב העבודה שדרש ג׳ון פוגרטי.''',
'''זה כמעט אוסף להיטים: Travelin' Band הוא רוקנרול מהיר בסגנון ליטל ריצ׳רד, Up Around the Bend הוא שיר שמח על יציאה לדרך, Lookin' Out My Back Door הוא שיר קאנטרי מצחיק עם חיות מדברות, Run Through the Jungle הוא שיר אפל ומאיים, ו־Who'll Stop the Rain, שיר עצוב על הגשם שלא נגמר, שנכתב לפי פוגרטי אחרי ההופעה בוודסטוק ונשמע גם כמו שיר על וייטנאם. והאלבום כולל גרסה של 11 דקות ל־I Heard It Through the Grapevine, עם ג׳אם גיטרה ארוך.''',
'''Cosmo's Factory הוא השיא המסחרי והאמנותי של הלהקה. שישה משיריו יצאו בסינגלים, שני שירים בכל תקליטון, וכולם הפכו ללהיטים. זמן קצר אחר כך התחילו מתחים בלהקה, בעיקר בין ג׳ון פוגרטי לאחיו טום, שעזב שנה אחר כך. אבל השירים האלה הפכו לחלק מהפסקול של אמריקה, והם מושמעים עד היום בסרטים, בפרסומות וברדיו.''',
'''זה אלבום מושלם למכונית. השוו את I Heard It Through the Grapevine כאן לגרסת הטמפטיישנס (אלבום 158): אותו שיר, פעם במוטאון עם הרמוניות, ופעם כג׳אם רוק ארוך של להקת מוסך.''',
], [
('Up Around the Bend', 'שיר שמח ומלא אנרגיה על יציאה לדרך, עם ריף גיטרה שאי אפשר לשכוח.'),
("Who'll Stop the Rain", 'שיר עצוב ויפה על גשם שלא נגמר, שנשמע כמו שיר על כל התקופה.'),
('Run Through the Jungle', 'שיר אפל ומאיים, עם הדהודים ומפוחית, על אמריקה מלאת רובים.'),
])

add(175, [
'''ב־1970 אריק קלפטון היה אחד הגיטריסטים המפורסמים בעולם (אלבומים 73 ו־88), וגם מאוהב נואשות בפאטי בויד, אשתו של חברו הטוב ג׳ורג׳ הריסון. הוא הקים להקה חדשה, Derek and the Dominos, כדי להתחבא מאחורי שם בדוי, ונסע להקליט במיאמי עם המפיק טום דאוד. באחת ההופעות של האחים אולמן הוא פגש את הגיטריסט דואן אולמן, והזמין אותו להצטרף להקלטות. האלבום הכפול יצא בסוף 1970.''',
'''כמעט כל השירים הם שירי אהבה נכזבת, ורובם בלוז. קלפטון ודואן אולמן מנגנים יחד ונגד זה, גיטרה מול גיטרה, והשילוב ביניהם הוא הלב של האלבום. Bell Bottom Blues הוא שיר תחנונים כואב, Key to the Highway הוא ג׳אם בלוז ארוך ורגוע, ו־Little Wing היא גרסה לשיר של ג׳ימי הנדריקס (אלבום 105), שמת שבועות ספורים אחרי ההקלטה. ובסוף מגיע Layla, שמבוסס על סיפור אהבה פרסי עתיק: ריף גיטרה בלתי נשכח, צעקה של אהבה, ואז סיום פסנתר שקט ויפהפה.''',
'''האלבום נכשל בהתחלה, ורבים אפילו לא ידעו שקלפטון מאחוריו. רק כשהשיר Layla יצא מחדש כסינגל ב־1972, הוא הפך ללהיט ענק, והאלבום נחשב היום לשיא של קלפטון. פאטי בויד נפרדה מהריסון והתחתנה עם קלפטון כעבור כמה שנים, ודואן אולמן נהרג בתאונת אופנוע ב־1971.''',
'''שמעו את Layla עד הסוף, כולל חלק הפסנתר. אחר כך חזרו ל־Key to the Highway: כאן שומעים הכי טוב את השיחה בין שני הגיטריסטים, שנשמעים כמו שני חברים שמסיימים זה את המשפטים של זה.''',
], [
('Layla', 'ריף מפורסם, צעקה של אהבה אסורה, וסיום פסנתר ארוך ושקט.'),
('Bell Bottom Blues', 'שיר תחנונים כואב, אחד השירים הכי אישיים של קלפטון.'),
('Key to the Highway', 'בלוז ישן שהופך לשיחה ארוכה ורגועה בין שתי גיטרות.'),
])

add(176, [
'''באוגוסט 1969, שבוע אחרי וודסטוק, מיילס דייוויס כינס באולפן של Columbia בניו יורק קבוצה גדולה של נגנים: שני קלידנים ולפעמים שלושה, שני בסיסטים, שניים־שלושה מתופפים, קלרינט בס, סקסופון והגיטריסט הבריטי הצעיר ג׳ון מקלפלין. הוא נתן להם רק רעיונות קצרים, אקורד או מקצב, ונתן להם לנגן שעות. המפיק טאו מסרו חתך וחיבר אחר כך את ההקלטות, כמו בסרט. התוצאה, אלבום כפול, יצאה באביב 1970.''',
'''זו מוזיקה סמיכה, מסתורית ופתוחה: מקצבים חוזרים של רוק ופאנק, בס שחוזר על אותו מוטיב, קלידים חשמליים שמרחפים, והחצוצרה של מיילס, עם הדהוד גדול, חותכת את האוויר. Pharaoh's Dance ושיר הנושא נמשכים כל אחד כעשרים דקות ויותר, ונשמעים כמו מסע בתוך יער חשוך. Miles Runs the Voodoo Down מושפע מהגרוב של ג׳ימי הנדריקס, ו־Spanish Key זז בקצב מהיר יותר, עם גיטרה מפוזזת.''',
'''Bitches Brew הפך לאחד האלבומים הנמכרים ביותר של מיילס, והגיע לקהל רחב בהרבה מזה של הג׳אז. הוא פתח את עידן הפיוז׳ן, השילוב בין ג׳אז לרוק, וכמעט כל נגן בו הקים אחר כך הרכב משפיע משלו: Weather Report, Return to Forever, Mahavishnu Orchestra. חובבי ג׳אז שמרנים כעסו, אבל קהל רוק צעיר גילה דרכו את הג׳אז. מיילס עצמו, שהיה אז בן ארבעים ושלוש, הופיע בשנים הבאות באולמות רוק גדולים, לצד להקות כמו גרייטפול דד, והביא את הג׳אז לקהל חדש.''',
'''התחילו ב־In a Silent Way (אלבום 145), האלבום הקודם והשקט יותר, ואז עברו לכאן. תנו לזה זמן: זו לא מוזיקה של מלודיות אלא של אווירה, ובהאזנה השנייה והשלישית היא נפתחת.''',
], [
('Bitches Brew', 'יצירת הנושא: 27 דקות של אווירה אפלה, הדהודים וחצוצרה שחותכת את החושך.'),
('Miles Runs the Voodoo Down', 'גרוב איטי ומגניב בהשראת ג׳ימי הנדריקס, עם מיילס במיטבו.'),
('Spanish Key', 'קטע מהיר ותוסס יותר, עם גיטרה של ג׳ון מקלפלין שמשתלבת בקצב.'),
])

add(177, [
'''ספיריט היו להקה מלוס אנג׳לס עם הרכב יוצא דופן: הגיטריסט והכותב הצעיר רנדי קליפורניה, שניגן בנעוריו עם ג׳ימי הנדריקס, והמתופף הקירח אד קאסידי, בעלה של אמו ונגן ג׳אז ותיק, שהיה מבוגר מהאחרים בעשרים שנה ויותר. הם שילבו רוק, ג׳אז ופסיכדליה. Twelve Dreams of Dr. Sardonicus, האלבום הרביעי שלהם, יצא בסוף 1970, בהפקת דייוויד בריגס, שעבד עם ניל יאנג (אלבום 185).''',
'''השירים זורמים זה לתוך זה כמו מחזור, עם הפקה עשירה, הרמוניות, קלידים ואפקטים מתוחכמים. Nature's Way הוא שיר רך ועצוב על הטבע שמאותת שמשהו לא בסדר, אחד משירי האיכות הסביבה המוקדמים ברוק. Animal Zoo הוא שיר מצחיק ומקפץ על חיי הלהקה, Mr. Skin הוא פאנק־רוק עליז עם כלי נשיפה, ו־Nothin' to Hide פותח את האלבום ברוק מלא אנרגיה. בסוף יש שירים אפלים יותר על מלחמה ועל עתיד מאיים. רנדי קליפורניה היה בן תשע עשרה בלבד, וכתב את רוב השירים, עם חוש מלודי שמזכיר את הביטלס, והרבה סקרנות לצלילים חדשים.''',
'''האלבום לא נמכר טוב כשיצא, והלהקה התפרקה זמן קצר אחר כך. אבל עם השנים הוא מכר יותר ויותר, ונחשב היום לאחד האלבומים המלוטשים והנעימים של הפסיכדליה המאוחרת. Nature's Way נשאר שיר מוכר ואהוב. המפיק דייוויד בריגס דחף את הלהקה לעבוד על כל פרט, והתוצאה נשמעת מלוטשת ועשירה, הרבה יותר מהאלבומים הקודמים שלה.''',
'''שמעו את האלבום ברצף, כי המעברים בין השירים חלק מהחוויה. Nature's Way הוא מקום טוב להתחיל בו: שיר קצר וחכם שמרגיש רלוונטי היום יותר מאשר ב־1970.''',
], [
("Nature's Way", 'שיר רך ועצוב על הטבע שמאותת שמשהו לא בסדר, מהשירים הסביבתיים הראשונים ברוק.'),
('Animal Zoo', 'שיר מצחיק ומקפץ על החיים בלהקת רוק, עם הרמוניות שמחות.'),
('Mr. Skin', 'רוק עליז עם כלי נשיפה, על המתופף הקירח של הלהקה.'),
])

add(178, [
'''ארבעה בחורים ממעמד הפועלים של בירמינגהם, עיר תעשייתית אפורה במרכז אנגליה, ניגנו בלוז רוק תחת שם אחר עד שהחליטו להפוך למשהו מפחיד. הם לקחו את השם Black Sabbath מסרט אימה, והבסיסט גיזר באטלר כתב מילים על השטן, על כוחות אפלים ועל חלומות רעים. הגיטריסט טוני איומי, שאיבד קצות אצבעות בתאונה במפעל, כיוון את הגיטרה נמוך כדי שיהיה לו קל יותר לנגן, וזה נתן לה צליל כבד ועמוק. אלבום הבכורה הוקלט כמעט כמו הופעה, ביום אחד, ויצא ביום שישי ה־13 בפברואר 1970.''',
'''השיר הפותח, Black Sabbath, מתחיל בגשם, רעמים ופעמון כנסייה, ואז מגיע ריף איטי וכבד, בנוי על מרווח צלילים שנחשב פעם ל"מרווח של השטן", והקול של אוזי אוסבורן שואל בבהלה מי זה שעומד מולו. The Wizard פותח במפוחית, N.I.B. נפתח בסולו בס, ו־Behind the Wall of Sleep מושפע מסיפורי אימה. הכול כבד, איטי ואפל, אבל מתחת לזה יש שורשים ברורים של בלוז וג׳אז.''',
'''המבקרים שנאו את האלבום, אבל הקהל אהב אותו מאוד, והוא הגיע לעשירייה הראשונה בבריטניה. היום הוא נחשב לאלבום הראשון של ההבי מטאל: הצליל, הנושאים והאווירה שלו הולידו ז׳אנר שלם, מדום ועד בלאק מטאל. שנה אחר כך הם הוציאו את Paranoid (אלבום 184), שהפך אותם לכוכבים.''',
'''שמעו את השיר Black Sabbath בחושך ובקול רם, עם אוזניות. אחר כך השוו ללד זפלין (אלבום 154): שתי להקות בריטיות מאותה תקופה ששתיהן בנו על בלוז, אבל הלכו לכיוונים שונים מאוד.''',
], [
('Black Sabbath', 'גשם, פעמון וריף איטי ומבשר רעות: הרגע שבו נולד ההבי מטאל.'),
('N.I.B.', 'נפתח בסולו בס ומתגלגל לריף קצבי, עם אוזי ששר מנקודת המבט של השטן.'),
('The Wizard', 'מפוחית פרועה וריף גדול, על קוסם מסתורי שמביא שמחה.'),
])

add(179, [
'''The Doors עברו שנה קשה ב־1969: ג׳ים מוריסון הועמד לדין אחרי הופעה סוערת במיאמי, הופעות בוטלו, והאלבום הקודם, עם כלי נשיפה ומיתרים, אכזב רבים מהמעריצים. Morrison Hotel, שיצא בתחילת 1970, היה חזרה לשורשים: רוק בלוזי, מחוספס ופשוט יותר. שם האלבום לקוח ממלון זול בלוס אנג׳לס, שבחלון שלו צולמה העטיפה, והצדדים של התקליט נקראו על שם שני מקומות בעיר: Hard Rock Cafe ו־Morrison Hotel.''',
'''Roadhouse Blues פותח את האלבום בבוגי חזק, עם מפוחית של ג׳ון סבסטיאן מלהקת Lovin' Spoonful, וקולו של מוריסון נשמע גס ורועם יותר מבעבר. Peace Frog הוא שיר פאנקי עם גיטרת וואה־וואה ומילים על אלימות ועל זיכרון ילדות של תאונה, Waiting for the Sun הוא שיר מסתורי ומרחף, ו־Queen of the Highway הוא שיר אהבה לחברה של מוריסון. יש גם בלדות שקטות כמו Indian Summer ו־Blue Sunday. בחלק מהשירים מנגן בבס נגן אורח, כי לדורז לא היה בסיסט קבוע, והקלידן ריי מנזרק מילא את החלק הזה בהופעות ביד שמאל.''',
'''האלבום החזיר את הלהקה למקום טוב אצל המבקרים והקהל, וסלל את הדרך ל־L.A. Woman, האלבום האחרון עם מוריסון, שמת ב־1971. Roadhouse Blues הפך לאחד השירים המוכרים ביותר של הלהקה ולסטנדרט של להקות בר בכל העולם. הגיטרה של רובי קריגר, עם צליל של בלוז ושל פלמנקו, והתופים של ג׳ון דנסמור, נותנים לשירים בסיס חזק ויציב.''',
'''שמעו את Roadhouse Blues אחרי The End מאלבום הבכורה שלהם (אלבום 93): מאותה להקה, מהמיסטיקה הפסיכדלית לבוגי בר בועט. זה טוב במיוחד בנסיעה.''',
], [
('Roadhouse Blues', 'הפותח: בוגי בועט עם מפוחית ופסנתר, ומוריסון בקול גס ורועם.'),
('Peace Frog', 'שיר פאנקי עם גיטרת וואה־וואה, על דם ברחובות ועל זיכרון ילדות.'),
('Waiting for the Sun', 'שיר מסתורי ומרחף, עם גיטרה כבדה וקול מוריסון שמחכה לשחר.'),
])

add(180, [
'''קארן וריצ׳רד קרפנטר, אחות ואח מפרברי לוס אנג׳לס, התחילו בשלישיית ג׳אז קטנה ועברו לפופ רך. קארן, בתחילה המתופפת, התגלתה כזמרת בעלת קול עמוק, חם ונקי להפליא, וריצ׳רד כתב, עיבד ובנה הרמוניות, לעתים עם עשרות שכבות של הקלטת קולות שלהם עצמם. הרב אלפרט, מבעלי חברת A&M, החתים אותם, ו־Close to You, האלבום השני שלהם, יצא ב־1970.''',
'''שיר הנושא, (They Long to Be) Close to You, הוא שיר של ברט בכרך והאל דייוויד שכבר הוקלט לפני כן ולא הצליח. בגרסה של הקרפנטרס, עם פסנתר עדין, חצוצרה רכה והרמוניות קול כמו ענן, הוא הגיע למקום הראשון באמריקה. We've Only Just Begun נכתב במקור כג׳ינגל לפרסומת של בנק, וריצ׳רד שמע אותו בטלוויזיה והפך אותו לשיר חתונה אהוב. הקול של קארן, קרוב מאוד למיקרופון, נשמע כאילו היא שרה רק לכם. ריצ׳רד עיבד כל שיר בקפידה, עם פסנתר, כלי נשיפה וכלי קשת, כך שהקול של קארן תמיד נשאר במרכז, כמו תכשיט בתוך קופסה.''',
'''בזמן שהרוק היה רועש ופרוע, הקרפנטרס הציעו משהו אחר: פופ נקי, מדויק ורגשי. המבקרים זלזלו בהם במשך שנים כמשהו "לא מגניב", אבל הם מכרו עשרות מיליוני תקליטים, ומוזיקאים רבים, מסוניק יות׳ ועד מדונה, דיברו על ההשפעה שלהם. קארן קרפנטר מתה ב־1983, בגיל 32, מסיבוכים של הפרעת אכילה, והקול שלה נחשב עד היום לאחד הקולות היפים של הפופ.''',
'''שמעו את Close to You בשקט ובאוזניות, והקשיבו להרמוניות: כל הקולות שאתם שומעים הם של קארן וריצ׳רד בלבד. זה אלבום טוב גם לשיחה על מה הופך שיר פופ פשוט לשיר נצחי.''',
], [
('(They Long to Be) Close to You', 'שיר של בכרך ודייוויד שהגיע למקום הראשון, עם הרמוניות רכות כמו ענן.'),
("We've Only Just Begun", 'נולד כג׳ינגל של פרסומת לבנק והפך לשיר חתונה קלאסי.'),
('Love Is Surrender', 'שיר קצבי ושמח עם שורשים בגוספל, שמראה את הצד העליז של הצמד.'),
])

add(181, [
'''סטיבן סטילס היה אחד הכוחות המוזיקליים של באפלו ספרינגפילד (אלבום 80) ושל קרוסבי, סטילס ונאש (אלבומים 138 ו־183): זמר, גיטריסט, קלידן ובסיסט, שיכול היה לנגן כמעט הכול בעצמו. באלבום הסולו הראשון שלו, שהוקלט בחלקו בלונדון ויצא בסוף 1970, הוא הזמין חברים מפורסמים: ג׳ימי הנדריקס מנגן בשיר אחד, אריק קלפטון בשיר אחר, ורינגו סטאר מתופף בשניים. האלבום מוקדש להנדריקס, שמת זמן קצר לפני שיצא.''',
'''Love the One You're With, השיר הפותח, הוא המנון שמח עם תופי פלדה, אורגן ומקהלה, שמציע פתרון פשוט לגעגועים: לאהוב את מי שנמצא לידך. אחריו באים שירים מגוונים: Do for the Others הוא שיר אקוסטי ורך, Old Times Good Times כולל סולו גיטרה של הנדריקס, ו־Go Back Home הוא בלוז כבד עם גיטרה של קלפטון. Black Queen הוא בלוז אקוסטי פרוע שהוקלט, לפי הסיפור, בלילה אחד ואחרי לא מעט טקילה, ו־We Are Not Helpless נסגר במקהלה גדולה של חברים.''',
'''Love the One You're With הפך ללהיט, והאלבום נמכר היטב. הוא מראה את סטילס כמוזיקאי רב־גוני במיוחד, שמשלב רוק, פולק, בלוז, גוספל ומקצבים לטיניים. זו גם אחת ההקלטות האחרונות שבהן השתתף הנדריקס, ולכן יש לה מקום מיוחד בזיכרון של התקופה. סטילס ניגן באלבום כמעט בכל הכלים, והוא אחד האלבומים הבודדים באותה תקופה שבהם אמן אחד מתחבר לכל כך הרבה כוכבים גדולים בבת אחת.''',
'''שמעו את Love the One You're With, ואז את Black Queen: מהשיר המלוטש והשמח ביותר, להקלטה הכי גולמית באלבום, רק סטילס והגיטרה, בלי שום ליטוש.''',
], [
("Love the One You're With", 'הפותח: המנון שמח עם תופי פלדה ומקהלה, הלהיט הגדול של האלבום.'),
('Old Times Good Times', 'שיר קצבי עם סולו גיטרה של ג׳ימי הנדריקס, מההקלטות האחרונות שלו.'),
('Black Queen', 'בלוז אקוסטי פרוע וגולמי, סטילס לבד עם הגיטרה, כמו בלילה מאוחר.'),
])

add(182, [
'''אחרי פירוק הביטלס, ג׳ון לנון עבר עם יוקו אונו טיפול פסיכולוגי אינטנסיבי אצל ארתור יאנוב, שטען שכדי להשתחרר מכאב ילדות צריך לחוות אותו מחדש, לפעמים בצעקות. לנון, שאביו עזב אותו ואמו נהרגה כשהיה נער, יצא מהטיפול עם שירים חשופים ובוטים. הוא הקליט אותם בסוף 1970 עם הרכב קטן: רינגו סטאר על תופים, קלאוס וורמן על בס, ופיל ספקטור כשותף להפקה. האלבום יצא בדצמבר.''',
'''אחרי ההפקות העשירות של הביטלס (אלבום 143), זה כמעט עירום: פסנתר או גיטרה, בס, תופים, וקול שנשבר. Mother פותח בפעמוני לוויה ומסתיים בצעקות קורעות לב של ילד שקורא להוריו. Working Class Hero הוא שיר אקוסטי מר על מערכת שמדכאת אנשים מגיל צעיר. Love הוא שיר אהבה פשוט ויפהפה, ו־God מונה את כל מה שלנון כבר לא מאמין בו, מהתנ״ך ועד אלביס ודילן, ומסתיים בהכרזה שגם הביטלס כבר מאחוריו: "החלום נגמר".''',
'''זה אחד האלבומים האישיים והכנים ביותר ששם גדול בפופ הוציא אי פעם, והוא השפיע על דורות של כותבים שהעזו לכתוב על כאב, משפחה וטראומה בלי לייפות. באותו יום יצא גם אלבום של יוקו אונו עם עטיפה כמעט זהה, ניסיוני וצורח. שנה אחר כך לנון הוציא את Imagine, רך ומלודי יותר, שהפך להצלחה ענקית.''',
'''זה לא אלבום קל להאזנה, וכדאי לבחור לו רגע שקט. אחרי Mother, שמעו את Love כדי לנשום, ואז את God: לנון מסכם בו את כל שנות השישים, והשורה האחרונה שלו היא אחד הרגעים החשובים בתולדות הפופ.''',
], [
('Mother', 'פעמוני לוויה, פסנתר איטי וצעקות של ילד נטוש: פתיחה מטלטלת.'),
('God', 'רשימה של כל מה שלנון כבר לא מאמין בו, עד ההכרזה "החלום נגמר".'),
('Working Class Hero', 'שיר אקוסטי מר וחריף על מערכת שמדכאת אנשים מילדות.'),
])

add(183, [
'''כשקרוסבי, סטילס ונאש הצליחו מאוד עם אלבום הבכורה (אלבום 138), הם רצו להוסיף נגן שיחזק אותם על הבמה, ובחרו בניל יאנג, חברו של סטילס מבאפלו ספרינגפילד (אלבום 80). יאנג הביא איתו גיטרה חשמלית מחוספסת ושירים שקטים ומוזרים. הם הופיעו יחד בוודסטוק, ובתחילת 1970 יצא Déjà vu, שהקלטתו נמשכה חודשים ארוכים של עבודה, ריבים ועצב: בת הזוג של דייוויד קרוסבי נהרגה בתאונת דרכים בתקופת ההקלטות.''',
'''כל אחד מהארבעה הביא שירים משלו, וההרמוניות מחברות ביניהם. Carry On של סטילס פותח בקצב סוער, Teach Your Children של גראהם נאש הוא שיר עם גיטרת סטיל של ג׳רי גרסיה מגרייטפול דד, על הורים וילדים שלומדים זה מזה, ו־Our House, גם של נאש, הוא שיר מתוק על חיים משותפים עם ג׳וני מיצ׳ל. Helpless של יאנג הוא שיר איטי וחולמני על עיירה בצפון אונטריו, Almost Cut My Hair של קרוסבי הוא שיר מחאה זועם, ו־Woodstock, שיר של ג׳וני מיצ׳ל, הופך כאן להמנון רוק חשמלי.''',
'''Déjà vu הגיע למקום הראשון באמריקה ונמכר במיליוני עותקים, והוא נחשב לאחד האלבומים שמגלמים את רוח דור וודסטוק. אבל ארבעת האגו לא יכלו לעבוד יחד לאורך זמן, והרביעייה התפרקה והתאחדה פעמים רבות בעשורים הבאים. ההקלטות היו ארוכות ומדוקדקות, ולפי הסיפורים ההרמוניות בחלק מהשירים דרשו עשרות ניסיונות עד שהגיעו לצליל הרצוי.''',
'''שמעו את Woodstock כאן ואז את הגרסה של ג׳וני מיצ׳ל, שכתבה אותו: היא שרה אותו בשקט, כמעט כתפילה, והם הופכים אותו לחגיגה רועשת. אותו שיר, שתי דרכים לזכור את אותו סוף שבוע.''',
], [
('Teach Your Children', 'שיר עם מתוק על הורים וילדים, עם גיטרת סטיל של ג׳רי גרסיה.'),
('Helpless', 'שיר איטי וחולמני של ניל יאנג על עיירת ילדותו בקנדה.'),
('Woodstock', 'השיר של ג׳וני מיצ׳ל בגרסת רוק חשמלית והרמוניות גדולות.'),
])

add(184, [
'''אחרי אלבום הבכורה (אלבום 178), בלאק סבאת׳ חזרו לאולפן בלונדון כמה חודשים בלבד אחר כך. האלבום נקרא במקור War Pigs, על שם השיר הפותח, אבל חברת התקליטים חששה משם שנשמע כמו מחאה נגד מלחמת וייטנאם, ובחרה בשם של שיר אחר. הבעיה: העטיפה כבר צולמה, ולכן מופיע עליה לוחם עם חרב ומגן, שלא קשור בכלל לשם Paranoid. האלבום יצא בספטמבר 1970, והגיע למקום הראשון בבריטניה. ארבעת חברי הלהקה גדלו בברמינגהאם, עיר תעשייה אפורה ורועשת, ורבים שומעים בצליל הכבד שלהם את המפעלים ואת המכונות של העיר.''',
'''War Pigs פותח בצפירות ובריף איטי וכבד, ואוזי אוסבורן שר על גנרלים שמשלחים חיילים עניים למות, כמו מכשפות בטקס שחור. Paranoid, שיר הנושא, נכתב לפי הסיפור בתוך דקות ספורות כדי למלא את האלבום, והפך ללהיט הגדול ביותר של הלהקה. Iron Man נפתח בקול מעוות ובריף שכל גיטריסט מתחיל לומד, ומספר על אדם שנסע בזמן, חזר כאיש ברזל ונקם בעולם שהתעלם ממנו. באמצע, Planet Caravan הוא שיר שקט, מרחף וג׳אזי, שמראה צד אחר של הלהקה.''',
'''Paranoid הוא אחד האלבומים החשובים והמשפיעים בתולדות ההבי מטאל, ואולי אלבום המטאל המפורסם בעולם. הריפים של טוני איומי, הבס של גיזר באטלר, התופים של ביל וורד והקול של אוזי הפכו לתבנית לכל מה שבא אחר כך, ממטאליקה ועד להקות גראנג׳ כמו נירוונה.''',
'''שמעו את War Pigs מההתחלה ועד הסוף: יותר משבע דקות של סיפור מלחמה. אחר כך את Planet Caravan, כדי לשמוע שגם בתוך הרעש הכי גדול יש מקום לשקט.''',
], [
('War Pigs', 'צפירות וריף איטי, ושיר מחאה זועם על גנרלים ששולחים עניים למלחמה.'),
('Paranoid', 'השיר שנכתב בדקות ספורות להשלמת האלבום והפך ללהיט הגדול של הלהקה.'),
('Iron Man', 'ריף מפורסם וסיפור מדע בדיוני על איש ברזל שנוקם בעולם.'),
])

add(185, [
'''ב־1970 ניל יאנג היה עסוק בשתי להקות: הוא היה חבר בקרוסבי, סטילס, נאש ויאנג (אלבום 183), וגם הקליט עם להקת Crazy Horse הרועשת. After the Gold Rush, אלבום הסולו השלישי שלו, הוקלט בחלקו באולפן ביתי במרתף ביתו בקניון טופנגה ליד לוס אנג׳לס, עם נגנים מקרייזי הורס ועם נער בן 18 בשם נילס לופגרן, שניגן על פסנתר אף שהיה בכלל גיטריסט. האלבום יצא בספטמבר 1970.''',
'''שיר הנושא הוא שיר מסתורי וחלומי, רק קול גבוה, פסנתר וכלי נשיפה רך, על אבירים, על חייזרים ועל אסון סביבתי שמתקרב. Only Love Can Break Your Heart הוא שיר רך ויפה על לב שבור, ו־Tell Me Why פותח את האלבום בגיטרות אקוסטיות ובהרמוניות. מנגד, Southern Man הוא שיר רוק זועם עם גיטרה חשמלית רועשת, על הגזענות בדרום אמריקה, ו־When You Dance I Can Really Love הוא רוק כבד ושמח. הקול של יאנג, גבוה ושביר, מחזיק את כל הניגודים יחד.''',
'''After the Gold Rush נחשב לאחד האלבומים הטובים של יאנג, והוא הראה את שני הצדדים שלו שילוו אותו כל הקריירה: הזמר האקוסטי והפגיע, והגיטריסט הרועש והזועם. Southern Man גרם אפילו ללהקה הדרומית Lynyrd Skynyrd לענות לו בשיר Sweet Home Alabama.''',
'''שמעו את After the Gold Rush בשקט, עם המילים. ואז את Southern Man בקול רם: קשה להאמין שאותו אדם שר את שניהם באותו אלבום.''',
], [
('After the Gold Rush', 'שיר הנושא: פסנתר, קרן וקול גבוה, בחזון חלומי על אסון ועל תקווה.'),
('Only Love Can Break Your Heart', 'שיר רך ומנחם על לב שבור, מהשירים האהובים של יאנג.'),
('Southern Man', 'רוק חשמלי זועם על גזענות, עם גיטרה שנשמעת כמו צעקה.'),
])

add(186, [
'''אחרי שני אלבומים רועמים (אלבומים 154 ו־156) וסיבובי הופעות מתישים, ג׳ימי פייג׳ ורוברט פלאנט נסעו ב־1970 לבקתה קטנה בלי חשמל בהרי ויילס, Bron-Yr-Aur, שבה בילה פלאנט עם משפחתו בילדותו. שם, עם גיטרות אקוסטיות, נולדו רוב השירים של האלבום השלישי. הוא יצא באוקטובר 1970, עם עטיפה מיוחדת עם גלגל מסתובב שחושף תמונות דרך חורים.''',
'''הצד הראשון עדיין מוכר: Immigrant Song פותח בצעקה ובריף מהיר על ויקינגים, בהשראת סיור הופעות באיסלנד, ו־Since I've Been Loving You הוא בלוז איטי ומתייסר, מהביצועים הגדולים של פלאנט. אבל הצד השני אקוסטי ברובו: Gallows Pole הוא שיר עם עתיק שמאיץ לחגיגה של בנג׳ו ומנדולינה, Tangerine ו־That's the Way הם שירים רכים וכפריים, ו־Bron-Y-Aur Stomp הוא שיר עליז על טיול עם כלב. פלאנט התחיל לכתוב מילים אישיות יותר, על טבע, על חברים ועל חיי הכפר, ולא רק על אהבה ובלוז.''',
'''המבקרים והקהל היו מבולבלים בהתחלה: הם ציפו לעוד Whole Lotta Love. אבל עם השנים הבינו שזה האלבום שבו לד זפלין הראו כמה הם רחבים, ושהאהבה שלהם לפולק הבריטי אמיתית בדיוק כמו האהבה לבלוז. השילוב הזה הגיע לשיא באלבום הבא שלהם, עם Stairway to Heaven. ג׳ון פול ג׳ונס מנגן באלבום גם במנדולינה ובכלים נוספים, והנגינה האקוסטית של כל הלהקה מדויקת ומלאת חיים.''',
'''שמעו את Immigrant Song ואחריו את That's the Way: הלהקה הכי רועשת בעולם, ואז שיר שקט על חברות שנגמרה. השוו גם לפיירפורט קונבנשן (אלבום 169), שעשו מהכיוון ההפוך בדיוק את אותו חיבור בין רוק לפולק.''',
], [
('Immigrant Song', 'צעקה, ריף מהיר ושיר על ויקינגים: פתיחה של שתי דקות וחצי.'),
("Since I've Been Loving You", 'בלוז איטי ומתייסר, עם אורגן, גיטרה בוכייה וביצוע ענק של פלאנט.'),
('Gallows Pole', 'שיר עם עתיק שמתחיל בשקט ומאיץ לחגיגה של בנג׳ו, מנדולינה ותופים.'),
])

add(187, [
'''דיפ פרפל התחילו בסוף שנות השישים כלהקת פופ־רוק עם גרסאות לשירים של אחרים, והקלידן ג׳ון לורד אפילו כתב יצירה ללהקה ותזמורת סימפונית. ב־1969 הצטרפו הזמר איאן גילאן והבסיסט רוג׳ר גלובר, והגיטריסט ריצ׳י בלקמור רצה ללכת לכיוון אחר: רוק רועש, מהיר וכבד. In Rock, שיצא באמצע 1970, היה הצעד הראשון בדרך הזו, ועל העטיפה נראים פני חברי הלהקה חצובים בסלע, בפרודיה על הר ראשמור.''',
'''Speed King פותח בפיצוץ של רעש, תופים וגיטרה, ואז נכנס לרוקנרול מהיר עם שורות משירים של ליטל ריצ׳רד. Child in Time הוא לב האלבום: יצירה של עשר דקות שמתחילה באורגן שקט ובשירה רכה, מטפסת לצעקות גבוהות להפליא של גילאן, יוצאת לסולו גיטרה מהיר של בלקמור וחוזרת. Flight of the Rat ו־Hard Lovin' Man הם שירי רוק כבדים ומהירים, עם דו־קרב בין הגיטרה של בלקמור לאורגן המעוות של לורד. גילאן, שהיה אז זמר צעיר מאוד, הגיע בשירה לטונים גבוהים שנשמעו כמו צרחה, והפך לאחד הקולות המוכרים של הרוק הכבד.''',
'''יחד עם לד זפלין ובלאק סבאת׳ (אלבומים 154 ו־178), דיפ פרפל הם אחת משלוש הלהקות הבריטיות שנחשבות לאבות ההארד רוק וההבי מטאל. In Rock נתן את הצליל שלהם: אורגן כבד ומעוות לצד גיטרה מהירה, והשפעות של מוזיקה קלאסית. אחריו הם הוציאו אלבומים מצליחים עוד יותר, כולל Machine Head עם Smoke on the Water.''',
'''שמעו את Child in Time מההתחלה עד הסוף, עם עוצמה גבוהה. זה אחד השירים שמראים איך הרוק הכבד של שנות השבעים שאל מהמוזיקה הקלאסית: מבנה ארוך, התחלה שקטה, שיא וחזרה.''',
], [
('Child in Time', 'עשר דקות של דרמה: אורגן שקט, צעקות גבוהות וסולו גיטרה מהיר.'),
('Speed King', 'פתיחה רועשת שהופכת לרוקנרול מהיר עם מחווה לליטל ריצ׳רד.'),
("Hard Lovin' Man", 'רוק כבד ופרוע עם דו־קרב בין גיטרה לאורגן מעוות.'),
])

add(188, [
'''Astral Weeks של ואן מוריסון (אלבום 132) קיבל שבחים עצומים אבל כמעט לא נמכר. למוריסון היו אשה וחשבונות לשלם, ובאלבום הבא, Moondance, שיצא בתחילת 1970, הוא רצה שירים עם מבנה ברור, שיוכלו להתנגן ברדיו. הוא עבר לגור באזור וודסטוק במדינת ניו יורק, והקליט את האלבום בניו יורק עם להקה משלו, עם כלי נשיפה, פסנתר וזמרות ליווי, והפעם גם הפיק אותו בעצמו.''',
'''התוצאה היא שילוב של סול, ג׳אז, רוק ופולק, מלא שמחה. And It Stoned Me פותח בזיכרון ילדות על יום גשום ומים מנחל שהרגישו כמו חוויה רוחנית. שיר הנושא, Moondance, הוא ג׳אז סווינג רך על ערב סתיו של אהבה, עם פסנתר וחליל. Crazy Love הוא שיר אהבה שקט בקול גבוה ורך, Caravan הוא שיר על רדיו ועל מוזיקה שמלאה בכלי נשיפה, ו־Into the Mystic, אולי השיר הכי אהוב שלו, הוא שיר מסתורי על ים, על ספינות ועל חיבור לנצח.''',
'''Moondance היה ההצלחה המסחרית הגדולה הראשונה של מוריסון כאמן סולו, והוא נשאר אחד האלבומים האהובים שלו. שירים כמו Moondance, Into the Mystic ו־Crazy Love הפכו לסטנדרטים, בוצעו על ידי זמרים רבים ומושמעים בחתונות, בסרטים ובפרסומות. הוא הוכיח שאפשר להיות מוזיקאי רוחני ומסתורי גם בשיר של שלוש דקות.''',
'''שמעו את Into the Mystic בערב, רצוי ליד הים או לפחות עם עיניים עצומות. והשוו ל־Astral Weeks (אלבום 132): אותו חיפוש אחר רגע קסום, אבל כאן הוא בא עם מנגינות שאפשר לשרוק.''',
], [
('Into the Mystic', 'שיר מסתורי ויפהפה על ים וספינות, אולי השיר האהוב ביותר של ואן מוריסון.'),
('Moondance', 'שיר הנושא: ג׳אז סווינג רך על ערב סתיו מאוהב, עם פסנתר וחליל.'),
('And It Stoned Me', 'הפותח: זיכרון ילדות על מים מנחל ועל רגע שהרגיש כמו קסם.'),
])

add(189, [
'''ב־1970 הגרייטפול דד שינו כיוון: אחרי שנים של אלתורים פסיכדליים ארוכים (אלבום 165), הם התחילו לשיר שירים קצרים, אקוסטיים ומלאי הרמוניות, בהשראת קרוסבי, סטילס ונאש (אלבום 138) ומוזיקת קאנטרי וגוספל. באותה שנה הם הוציאו שני אלבומים כאלה, Workingman's Dead ו־American Beauty, שיצא בנובמבר. זו הייתה גם שנה קשה: גם אמו של ג׳רי גרסיה וגם אביו של פיל לש מתו בזמן העבודה עליו.''',
'''רוב המילים כתב רוברט האנטר, המשורר של הלהקה, והן נשמעות כמו שירי עם אמריקאיים ישנים. Box of Rain, שפותח את האלבום, כתב פיל לש לאביו החולה, Friend of the Devil הוא שיר קאנטרי קליל על נמלט מהחוק, ו־Sugar Magnolia הוא שיר אהבה שמח. Ripple הוא שיר פשוט ויפה על מוזיקה ועל דרך, עם מנדולינה, ו־Brokedown Palace הוא שיר פרידה רך ומנחם. והאלבום נסגר ב־Truckin', שיר על חיי הדרכים של הלהקה, עם השורה המפורסמת "איזה טיול ארוך ומוזר זה היה". ההרמוניות של הלהקה נשמעות כאן חמות ומלאות, כמו בערב של חברים סביב מדורה.''',
'''American Beauty הוא אחד האלבומים הנמכרים והאהובים של הדד, ורבים מהשירים שלו הפכו לחלק קבוע מההופעות שלהם במשך עשרים וחמש שנה. הוא גם הראה שהלהקה שנחשבה לסמל הפסיכדליה היא בעצם אחת הלהקות האמריקאיות ביותר, עם שורשים עמוקים בקאנטרי, בבלוגראס ובפולק.''',
'''שמעו את Ripple ו־Brokedown Palace ברצף: שני שירים שקטים ופשוטים שמרגישים כאילו נכתבו לפני מאה שנה. אחר כך שמעו את Dark Star מאלבום 165, וחשבו איך אותם אנשים ניגנו את שניהם.''',
], [
('Ripple', 'שיר פשוט ויפהפה על מוזיקה ועל דרך, עם מנדולינה והרמוניות רכות.'),
('Friend of the Devil', 'שיר קאנטרי קליל על נמלט מהחוק, מהשירים האהובים של הלהקה.'),
("Truckin'", 'שיר על חיי הדרכים, עם השורה המפורסמת על טיול ארוך ומוזר.'),
])

add(190, [
'''ניק דרייק היה סטודנט צעיר ושקט מקיימברידג׳, עם קול רך ונגינת גיטרה מיוחדת מאוד, כשהוציא את אלבום הבכורה שלו (אלבום 149). הוא לא נמכר, ודרייק עזב את הלימודים ועבר ללונדון. באלבום השני, Bryter Layter, המפיק ג׳ו בויד רצה להפוך אותו לנגיש יותר: עם להקה, עם כלי נשיפה, עם זמרות ליווי ועם עיבודים עשירים של רוברט קירבי. בהקלטות השתתפו נגנים מפיירפורט קונבנשן (אלבום 169), ג׳ון קייל מהוולווט אנדרגראונד (אלבום 91) ואחרים.''',
'''התוצאה היא אלבום יפהפה, רגוע ומעט ג׳אזי, עם מצב רוח של עיר גדולה בערב. שלושה קטעים אינסטרומנטליים מחלקים אותו, כמו פרקים. Hazey Jane II פותח בשמחה עם כלי נשיפה, At the Chime of a City Clock מתאר בדידות ברחובות לונדון, ו־Northern Sky הוא אולי שיר האהבה היפה ביותר של דרייק, עם פסנתר וצ׳לסטה של ג׳ון קייל. Poor Boy הוא שיר ג׳אזי עם זמרות ליווי שמלגלגות בחיבה על הזמר המסכן.''',
'''למרות העבודה הרבה, גם האלבום הזה כמעט לא נמכר. דרייק, שסבל מדיכאון ומביישנות קשה ולא אהב להופיע, התכנס עוד יותר בעצמו. הוא הקליט עוד אלבום אחד, שקט וחשוף, ומת ב־1974 בגיל 26. בשנות התשעים הוא התגלה מחדש, והיום השירים שלו מוכרים ואהובים יותר מאי פעם.''',
'''שמעו את Northern Sky בשקט, ברגע של אהבה או של געגועים. אחר כך השוו את האלבום ל־Five Leaves Left (אלבום 149): אותו קול, אבל כאן הוא לא לבד, והעיר כולה מתעוררת סביבו.''',
], [
('Northern Sky', 'שיר אהבה שקט ויפהפה, עם פסנתר וצ׳לסטה של ג׳ון קייל.'),
('Hazey Jane II', 'שיר עליז עם כלי נשיפה וגיטרה של ריצ׳רד תומפסון, הצד השמח של דרייק.'),
('At the Chime of a City Clock', 'שיר על בדידות בעיר הגדולה, עם סקסופון רך בערב לונדוני.'),
])

add(191, [
'''אננדה שנקר היה אחיינו של רבי שנקר (אלבום 111) ובנו של הרקדן ההודי המפורסם אודאי שנקר. הוא גדל בתוך עולם של מוזיקה ומחול, ולמד לנגן בסיטאר, אבל בניגוד לדודו, הוא התעניין מאוד ברוק המערבי. בסוף שנות השישים הוא נסע ללוס אנג׳לס, פגש מוזיקאים מקומיים, והקליט שם אלבום שמחבר בין השניים. הוא יצא ב־1970, בחברת Reprise.''',
'''זה מפגש מפתיע ומשעשע: סיטאר, טבלה ומקצבים הודיים, לצד גיטרה חשמלית, תופי רוק ובעיקר סינתיסייזר Moog, שהיה אז כלי חדש ונדיר. שני הקטעים המפורסמים הם גרסאות אינסטרומנטליות ללהיטי רוק: Jumpin' Jack Flash של הרולינג סטונס, שבו הסיטאר מנגן את הריף המפורסם, ו־Light My Fire של הדורס (אלבום 93), שנפתח בקצב איטי ומדיטטיבי. לצידם יש יצירות מקוריות כמו Metamorphosis, עם קצב דוהר ו־Moog מבעבע, ו־Sagar, יצירה שקטה ויפה שמתארת את הים. הקצב המהיר והקצבי של הטבלה פוגש את הבס והתופים של הרוק בצורה טבעית, ולפעמים קשה לדעת איפה נגמר האחד ומתחיל השני.''',
'''האלבום לא הצליח במיוחד כשיצא, ואננדה שנקר חזר להודו והמשיך לשלב בין מזרח ומערב לאורך כל הקריירה שלו. אבל בשנות התשעים תקליטנים ומפיקים בבריטניה גילו אותו מחדש, והוא הפך לאהוב במועדונים ולמקור לדגימות בהיפ הופ ובמוזיקה אלקטרונית. הוא נחשב היום לאחת הדוגמאות המוקדמות והמהנות ביותר לחיבור בין מוזיקה הודית לרוק.''',
'''שמעו את Jumpin' Jack Flash ואחר כך את Sounds of India של רבי שנקר (אלבום 111): דוד ואחיין, אחד שומר על המסורת בקפידה ואחד משחק איתה בחופשיות.''',
], [
("Jumpin' Jack Flash", 'הריף של הרולינג סטונס על סיטאר, עם תופי רוק ו־Moog: משעשע וקליט.'),
('Light My Fire', 'השיר של הדורס בגרסה איטית ומדיטטיבית, שנפתחת לאט לאט.'),
('Metamorphosis', 'קטע מקורי עם קצב דוהר, סיטאר וסינתיסייזר מבעבע, שהפך לאהוב במועדונים.'),
])

add(192, [
'''אחרי Tommy (אלבום 144), The Who הפכו לאחת הלהקות המצליחות בעולם, והם רצו להוציא אלבום הופעה שיראה את הצד הגולמי והרועש שלהם. הם הקליטו כמה הופעות, ובחרו את ההופעה בערב של 14 בפברואר 1970, באולם של אוניברסיטת לידס בצפון אנגליה. האלבום יצא במאי, עם עטיפה פשוטה שנראית כמו תקליט פיראטי, רק עם שם מוטבע בחותמת.''',
'''התקליט המקורי כולל שישה שירים בלבד, ורובם אינם להיטים של The Who אלא שירי רוקנרול ובלוז ישנים: Young Man Blues של מוס אליסון, Summertime Blues של אדי קוקרן ו־Shakin' All Over של ג׳וני קיד, כולם מנוגנים בעוצמה אדירה. פיט טאונסנד מכה בגיטרה, ג׳ון אנטוויסל מנגן על הבס כמו גיטרה מובילה, קית׳ מון מתופף בלי הפסקה ורוג׳ר דאלטרי צועק. My Generation (אלבום 59) נמתח כאן ל־15 דקות, עם קטעים מתוך Tommy ואלתורים. ההקלטה נעשתה בפשטות, כמעט בלי תיקונים, ולכן היא נשמעת טבעית ומשוחררת, כמו כל ערב רגיל של הלהקה.''',
'''Live at Leeds נחשב בעיני רבים לאלבום ההופעה הגדול ביותר בתולדות הרוק. הוא מראה למה The Who נחשבו אז ללהקת ההופעות החזקה בעולם: ארבעה נגנים שכל אחד מהם מנגן כאילו הוא לבד, ויחד זה נשמע כמו סערה. במהדורות מאוחרות יותר נוספו שירים רבים מאותו ערב, כולל ביצוע מלא של Tommy.''',
'''שמעו את האלבום בקול רם מאוד, כמו שהוא נועד. אחר כך השוו את My Generation כאן לגרסה המקורית באלבום 59: אותו שיר, חמש שנים אחרי, והילדים הזועמים הפכו לענקים.''',
], [
('Young Man Blues', 'הפותח: בלוז ישן שהופך למתקפה של תופים, בס וצעקות.'),
('Summertime Blues', 'רוקנרול של אדי קוקרן בגרסה כבדה ועוצמתית, שהפכה למפורסמת יותר מהמקור.'),
('My Generation', 'ההמנון הישן נמתח ל־15 דקות, עם קטעים מ־Tommy ואלתורים פרועים.'),
])

add(193, [
'''סופט מאשין היו חלק מ"סצנת קנטרברי", קבוצה של מוזיקאים מהעיר הקתדרלית הבריטית ששילבו פסיכדליה, ג׳אז, הומור והרבה חופש. בהתחלה הם היו להקה פסיכדלית שהופיעה במועדונים של לונדון לצד פינק פלויד (אלבום 89), אבל עד 1970 הם הפכו כמעט להרכב ג׳אז: המתופף והזמר רוברט וויאט, הקלידן מייק ראטלדג׳, הבסיסט יו הופר והסקסופוניסט אלטון דין. Third, שיצא ב־1970, הוא אלבום כפול עם ארבע יצירות, כל אחת צד שלם של תקליט.''',
'''Facelift, שהוקלט בחלקו בהופעה, נפתח ברעש מוזר של אורגן מעוות ומתפתח לקטעים ג׳אזיים חדים. Slightly All the Time הוא קטע רגוע ויפה עם סקסופון וחליל. Moon in June היא היצירה היחידה עם שירה: רוברט וויאט שר, מנגן על תופים וקלידים, ומספר בחצי הומור על חיים של מוזיקאי צעיר ועל אהבה, עם קולות שמוקלטים זה על גבי זה. Out-Bloody-Rageous, היצירה של ראטלדג׳, נפתחת ונסגרת בצלילים חוזרים ומהפנטים, ובאמצע ג׳אז מלא אנרגיה.''',
'''Third הוא אחד האלבומים החשובים של הרוק הבריטי הניסיוני, והראה שאפשר ללכת מהפסיכדליה אל הג׳אז בלי לאבד את האישיות. באותה שנה סופט מאשין הפכו ללהקת הרוק הראשונה שהופיעה בפסטיבל התזמורות הקלאסי של ה־BBC, ה־Proms. רוברט וויאט עזב כעבור שנה, וב־1973 נפל מחלון ונותר משותק, אבל המשיך קריירה מוערכת מאוד כזמר.''',
'''זה אלבום ארוך ודורש, כדאי לשמוע אותו צד אחרי צד ולא הכול ברצף. התחילו ב־Moon in June, הצד האישי והחם, ואחר כך השוו ל־Bitches Brew של מיילס דייוויס (אלבום 176) מאותה שנה: שני כיוונים שונים לאותו מפגש בין רוק לג׳אז.''',
], [
('Moon in June', 'היצירה היחידה עם שירה: רוברט וויאט מספר על חיים ואהבה, בחצי הומור ובהמון רגש.'),
('Slightly All the Time', 'קטע ג׳אז רגוע ויפה, עם סקסופון, חליל ובס מתנגן.'),
('Out-Bloody-Rageous', 'צלילים חוזרים ומהפנטים שנפתחים לג׳אז מלא אנרגיה, עם סקסופון וקלידים.'),
])

add(194, [
'''רוד סטיוארט היה זמר עם קול צרוד וייחודי, שהתפרסם בלהקה של ג׳ף בק. ב־1969 הוא הצטרף יחד עם רון ווד ללהקה Faces, שנוצרה משרידי הסמול פייסס (אלבום 126) אחרי שהזמר שלהם עזב, ובמקביל חתם על חוזה נפרד לאלבומי סולו. Gasoline Alley, אלבום הסולו השני שלו, יצא ב־1970, ורוב חברי ה־Faces מנגנים בו.''',
'''זה אלבום חם, מחוספס וקצת עצוב, שמשלב רוק, פולק וסול. שיר הנושא, שסטיוארט כתב עם רון ווד, הוא שיר געגועים לבית ולרחוב שבו גדל, עם גיטרות אקוסטיות וקול צרוד ומתגעגע. Country Comfort הוא שיר של אלטון ג׳ון ובארני טופין, שסטיוארט שר לפני שהם עצמם הפכו למפורסמים, ו־It's All Over Now הוא רוקנרול בועט ששרו גם הרולינג סטונס. יש גם שיר של בוב דילן, Only a Hobo, ושיר של הסמול פייסס, My Way of Giving. רון ווד מנגן בגיטרה אקוסטית וחשמלית בחום ובפשטות, והמנדולינה והכינור מוסיפים לשירים ניחוח של פאב אנגלי.''',
'''Gasoline Alley היה הצלחה צנועה, אבל הוא הניח את הבסיס לסגנון של סטיוארט בשנים הבאות: שילוב של כנות, הומור וקול שנשמע כמו חבר בבר. שנה אחר כך, עם Maggie May, הוא הפך לאחד הזמרים הגדולים בעולם. רבים רואים באלבומי הסולו הראשונים שלו את השיא האמנותי שלו.''',
'''שמעו את Gasoline Alley ואחריו את Country Comfort. אם אתם מכירים את רוד סטיוארט רק מהלהיטים המאוחרים שלו, תתפלאו: כאן הוא נשמע כמו זמר פולק מרחוב עני בלונדון.''',
], [
('Gasoline Alley', 'שיר הנושא: געגועים לבית, עם גיטרות אקוסטיות וקול צרוד ומתגעגע.'),
('Country Comfort', 'שיר של אלטון ג׳ון בביצוע חם ומלא רגש, לפני שאלטון עצמו הפך לכוכב.'),
("It's All Over Now", 'רוקנרול בועט וצרוד, עם הלהקה שמנגנת כאילו היא בפאב.'),
])

add(195, [
'''בשנים האחרונות של הביטלס, ג׳ורג׳ הריסון כתב הרבה שירים, אבל לנון ומקרטני הקצו לו רק שניים או שלושה בכל אלבום (אלבום 143). כשהלהקה התפרקה ב־1970, היה לו מאגר עצום של שירים שחיכו. הוא הקליט אותם עם המפיק פיל ספקטור ועם הרבה חברים: אריק קלפטון והלהקה שלו, רינגו סטאר, בילי פרסטון, וחברי להקת Badfinger. התוצאה יצאה בסוף 1970 כאלבום משולש: שלושה תקליטים בקופסה אחת.''',
'''הצליל הוא "חומת הקול" של ספקטור: הרבה גיטרות אקוסטיות, פסנתרים, תופים וכלי נשיפה שמתערבבים להדהוד ענק. My Sweet Lord הוא שיר תפילה שמח שמשלב "הללויה" ו"הרה קרישנה", ו־What Is Life הוא שיר אהבה קצבי ועליז. Isn't It a Pity הוא שיר עצוב וארוך על אנשים שפוגעים זה בזה, ו־Wah-Wah נכתב אחרי שהריסון עזב בכעס חזרות של הביטלס. התקליט השלישי כולו ג׳אמים חופשיים עם החברים. רבים מהשירים כתב הריסון עוד בימי הביטלס, ואפשר לשמוע בהם את הדרך הרוחנית שלו, בהשראת הודו ומורים שפגש שם.''',
'''All Things Must Pass הגיע למקום הראשון באמריקה ובבריטניה, ו־My Sweet Lord היה הסינגל הראשון של ביטל לשעבר שהגיע למקום הראשון. הוא הוכיח שהביטל ה"שקט" הוא כותב גדול בפני עצמו. בית משפט קבע מאוחר יותר ש־My Sweet Lord דומה מדי לשיר ישן בשם He's So Fine, והריסון אמר שזה קרה בלי כוונה.''',
'''התחילו בשני התקליטים הראשונים, השירים עצמם, והשאירו את הג׳אמים לפעם אחרת. שמעו את Isn't It a Pity ואחר כך את Something מאלבום 143: תשמעו כמה הריסון גדל בשנה אחת.''',
], [
('My Sweet Lord', 'שיר תפילה שמח עם גיטרת סלייד, "הללויה" ו"הרה קרישנה" באותו פזמון.'),
('What Is Life', 'שיר אהבה קצבי ועליז, עם כלי נשיפה וריף גיטרה מדבק.'),
("Isn't It a Pity", 'שיר ארוך ועצוב על אנשים שפוגעים זה בזה, שבונה לאט לאט לשיא גדול.'),
])

add(196, [
'''סיימון וגרפונקל (אלבומים 71 ו־125) הקליטו את האלבום האחרון שלהם בשנים 1969–1970, בזמן שהיחסים ביניהם התערערו: ארט גרפונקל טס לצלם סרט במקסיקו, ופול סיימון נשאר בניו יורק וכתב לבד. Bridge Over Troubled Water יצא בתחילת 1970, ובתוך שבועות היה לאחד האלבומים הנמכרים ביותר בעולם באותה תקופה. זמן קצר אחר כך הצמד נפרד.''',
'''שיר הנושא, שסיימון כתב וגרפונקל שר לבדו, מתחיל בפסנתר גוספל שקט ובקול צלול, וצומח לסוף עצום עם תזמורת ותופים. The Boxer, על צעיר שמגיע לעיר הגדולה ונשבר, מפורסם בפזמון "לַיי־לַה־לַיי" ובתוף עם הדהוד ענק. Cecilia הוא שיר שמח עם כלי הקשה שהוקלטו במסיבה, El Condor Pasa הוא שיר פרואני עתיק שהצמד הוסיף לו מילים, ו־The Only Living Boy in New York הוא שיר רך וכמעט עצוב שסיימון כתב לגרפונקל, שהיה רחוק.''',
'''האלבום זכה בפרסי הגראמי לאלבום השנה ולשיר השנה, ונמכר במיליוני עותקים. זה היה סוף מושלם לצמד: הוא מראה את סיימון ככותב בוגר שמשלב גוספל, מוזיקה לטינית ורוק, ואת גרפונקל כאחד הקולות היפים של התקופה. אחרי הפרידה, כל אחד מהם המשיך בקריירת סולו, והם התאחדו רק להופעות מיוחדות. ההפקה של רוי הלי, השותף הקבוע שלהם באולפן, נתנה לשירים צליל גדול ורחב, ולפעמים הוא נחשב כמעט לחבר שלישי בצמד.''',
'''שמעו את The Only Living Boy in New York בשקט, וחשבו על שני חברים שכבר מתרחקים זה מזה. אחר כך את So Long, Frank Lloyd Wright: שיר על אדריכל מפורסם, שגרפונקל, שלמד אדריכלות, שר, ורבים שומעים בו פרידה של סיימון מחברו.''',
], [
('Bridge Over Troubled Water', 'שיר הנושא: פסנתר גוספל וקולו של גרפונקל, שצומחים לשיא גדול ומרגש.'),
('The Boxer', 'סיפור על צעיר שנשבר בעיר הגדולה, עם פזמון "לַיי־לַה־לַיי" מפורסם.'),
('The Only Living Boy in New York', 'שיר רך ובודד שסיימון כתב לגרפונקל, כשכבר היו רחוקים.'),
])

add(197, [
'''קאט סטיבנס, בנו של בעל מסעדה יווני ואם שוודית, היה כוכב פופ צעיר בלונדון באמצע שנות השישים, עם להיטים קליטים ועיבודים גדולים. ב־1968 הוא חלה בשחפת קשה ואושפז לתקופה ארוכה. במהלך ההחלמה הארוכה הוא עבר שינוי: התחיל לקרוא ספרים רוחניים, לכתוב שירים פשוטים ואישיים יותר, ולחפש משמעות. Tea for the Tillerman, האלבום הרביעי שלו, יצא בסוף 1970. סטיבנס הקליט את האלבום עם הגיטריסט אלון דייוויס, והנגינה המשותפת של שתי הגיטרות האקוסטיות שלהם נותנת לשירים רוך וחום.''',
'''העיבודים פשוטים וחמים: גיטרות אקוסטיות, פסנתר, מעט כלי מיתר, והקול הרך והמעט צרוד של סטיבנס. Wild World הוא שיר פרידה מבוגרת שמאחל לאהובה לשעבר להיזהר בעולם, Father and Son הוא שיח בין אב שמבקש מבנו להירגע ולבן שחייב ללכת בדרכו, כשסטיבנס שר את שני התפקידים בשני קולות שונים. Where Do the Children Play? שואל מה יישאר לילדים בעולם של מכונות ובנייה, ו־Hard Headed Woman הוא שיר על חיפוש אחר אישה עצמאית וחזקה.''',
'''האלבום הפך את סטיבנס לכוכב בינלאומי, והשירים שלו הפכו לחלק מפסקול שנות השבעים. ב־1977 הוא התאסלם, שינה את שמו ליוסף אסלאם, ועזב את עולם הפופ לתקופה ארוכה. היום הוא מופיע שוב, ו־Father and Son ו־Wild World נשארו מהשירים האהובים של התקופה. את העטיפה, ציור צבעוני של איכר שותה תה ליד שולחן, צייר סטיבנס בעצמו, כמו את רוב העטיפות שלו באותן שנים.''',
'''שמעו את Father and Son ושימו לב לשני הקולות: הנמוך והרגוע של האב, והגבוה והנסער של הבן. זה אלבום מצוין לשיחה בין הורים וילדים, בדיוק על הנושא הזה.''',
], [
('Father and Son', 'שיח בין אב לבן, בשני קולות, על הצורך להתבגר וללכת בדרך שלך.'),
('Wild World', 'שיר פרידה בוגר ורך, שמאחל לאהובה להיזהר, עם מנגינה שנתקעת בראש.'),
('Where Do the Children Play?', 'הפותח: שאלה שקטה על עולם של מכונות ובניינים ומה יישאר לילדים.'),
])

add(198, [
'''טראפיק הייתה אחת הלהקות המעניינות של הפסיכדליה הבריטית (אלבום 108), אבל ב־1969 הזמר והמוזיקאי סטיב ווינווד עזב כדי להקים את Blind Faith עם אריק קלפטון. כשהלהקה ההיא התפרקה אחרי אלבום אחד, ווינווד התחיל להקליט אלבום סולו, וקרא לשני חבריו הוותיקים, המתופף ג׳ים קפלדי ונגן כלי הנשיפה כריס ווד, לעזור. בתוך זמן קצר הבינו שזה בעצם אלבום של טראפיק. John Barleycorn Must Die יצא באמצע 1970. ווינווד, שהיה עוד בשנות העשרים המוקדמות לחייו, ניגן כבר אז בכמה כלים ונחשב לאחד המוזיקאים המוכשרים באנגליה.''',
'''זה אלבום של שישה שירים ארוכים ורגועים, שמשלבים רוק, ג׳אז ופולק. Glad פותח בקטע אינסטרומנטלי של פסנתר ג׳אזי, עם סקסופון שמצטרף ומתחמם, ומתחבר ישירות ל־Freedom Rider, שיר קצבי עם חליל. Empty Pages הוא שיר רך עם אורגן חשמלי, ושיר הנושא הוא שיר עם אנגלי עתיק, מנוגן בגיטרות אקוסטיות וחליל, על ג׳ון ברליקורן, דמות שמסמלת את השעורה שהופכת לבירה ולוויסקי.''',
'''האלבום היה ההצלחה הגדולה ביותר של טראפיק באמריקה, והלהקה המשיכה ממנו לכיוון של ג׳אמים ארוכים וג׳אזיים. הוא נחשב לאחד הדוגמאות הראשונות לרוק "רגוע" ומנוגן היטב של שנות השבעים, וגם לחיבור מוקדם בין הרוק הבריטי לשירי העם המקומיים, בדומה למה שעשו פיירפורט קונבנשן (אלבום 169). הצליל של האלבום נשען הרבה על כלי הנשיפה של כריס ווד, שמנגן בחליל ובסקסופון ומוסיף צבעים של ג׳אז לשירי רוק ופולק.''',
'''שמעו את Glad ו־Freedom Rider ברצף, כמו יצירה אחת. אחר כך את John Barleycorn: שיר עם מלפני מאות שנים שנשמע טבעי לגמרי בתוך אלבום רוק.''',
], [
('Glad', 'קטע אינסטרומנטלי של פסנתר ג׳אזי וסקסופון, שנבנה בשמחה ובאנרגיה.'),
('Freedom Rider', 'שיר קצבי ומסתורי עם חליל וסקסופון, שממשיך ישר מתוך Glad.'),
('John Barleycorn', 'שיר עם אנגלי עתיק על השעורה שהופכת לבירה, בגיטרות אקוסטיות וחליל.'),
])

add(199, [
'''אלבום הבכורה של הסטוג׳ס (אלבום 171) נכשל, אבל ההופעות שלהם הפכו לאגדה: איגי פופ קפץ לקהל, התגלגל על שברי זכוכית והתנהג כמו חיה. באלבום השני הם רצו ללכוד את זה. באביב 1970 הם נסעו ללוס אנג׳לס, והמפיק דון גאלוצ׳י נתן להם לנגן יחד באולפן כאילו זו הופעה, עם איגי שר במיקרופון ביד. הם ניגנו כל שיר שוב ושוב, והשתמשו בביצוע הכי חי. Fun House יצא בקיץ 1970.''',
'''מהשנייה הראשונה של Down on the Street, הצליל נשמע כמו חדר חם ורועש: גיטרה מלוכלכת ומלאת וואה־וואה של רון אשטון, תופים שנשמעים קרובים מאוד, וקולו של איגי שצורח, נוהם ומקלל. Loose ו־T.V. Eye הם רוק פראי ומהיר, Dirt הוא בלוז איטי ומאיים, ו־1970 מסתיים בצעקות "I feel alright". בחצי השני מצטרף הסקסופוניסט סטיב מקאי, ו־Fun House ו־L.A. Blues הופכים לג׳אז חופשי ורעשני, כמעט לכאוס מוחלט.''',
'''גם Fun House נכשל, וחברת Elektra ויתרה על הלהקה. אבל עם השנים הוא נחשב לאחד האלבומים הגדולים של הרוק ולאחד מאבני היסוד של הפאנק. מוזיקאים כמו ג׳ק וייט מהוויט סטרייפס וסוניק יות׳ דיברו עליו כהשראה, והמבקרים מדרגים אותו כאחד האלבומים הרועשים והחיים ביותר שהוקלטו אי פעם. רון אשטון, הגיטריסט, נשאר לאורך השנים מקור השראה לגיטריסטים של פאנק, בזכות הצליל הפשוט, הרועש והאכזרי שלו.''',
'''שמעו את Down on the Street ו־T.V. Eye בקול רם. ואז, אם יש לכם אומץ, את L.A. Blues: חמש דקות של רעש שמסיימות את האלבום כמו דלת שנטרקת.''',
], [
('Down on the Street', 'הפותח: גיטרה מלוכלכת, קצב מהפנט ואיגי שנוהם. מרגיש כמו הופעה בחדר קטן.'),
('T.V. Eye', 'רוק פראי ומהיר, עם צעקות של איגי ועם גיטרה בוערת של רון אשטון.'),
('Dirt', 'בלוז איטי ומאיים, שבו איגי נשמע כמו חיה שמסתובבת בחושך.'),
])

add(200, [
'''ג׳יימס טיילור גדל במשפחה אמידה בצפון קרוליינה ובמסצ׳וסטס, סבל מדיכאון ואושפז בבית חולים פסיכיאטרי כנער, ואחר כך התמכר להרואין. ב־1968 הוא הקליט אלבום ראשון בלונדון, בחברה של הביטלס, שנכשל. הוא חזר לאמריקה, עבר גמילה, ועם המפיק פיטר אשר הקליט בלוס אנג׳לס את Sweet Baby James, שיצא בתחילת 1970. פיטר אשר, המפיק, היה גם זה שגילה אותו בלונדון, והוא ליווה אותו באולפן במשך שנים רבות.''',
'''הצליל שקט, חם וכמעט מינימלי: גיטרה אקוסטית עם נגינה עדינה ומדויקת, בס, תופים רכים, פסנתר של קרול קינג בכמה שירים, וקול רגוע שנשמע כמו חבר שמספר סיפור. שיר הנושא הוא שיר ערש של קאובוי, שטיילור כתב לאחיין שנקרא על שמו. Fire and Rain הוא שיר אישי וכואב על חברה שהתאבדה, על ההתמכרות ועל האשפוז, ואחד השירים המפורסמים של העשור. Country Road הוא שיר על הליכה בדרך לבד, ו־Steamroller הוא בלוז משעשע ומוגזם, שטיילור שר בקריצה.''',
'''Fire and Rain הפך ללהיט, והאלבום הפך את טיילור לכוכב ולסמל של גל ה"זמרים־כותבים" של תחילת שנות השבעים: שירים אישיים, שקטים וכנים, במקום רעש ומחאה. יחד עם קרול קינג, ג׳וני מיצ׳ל ואחרים הוא עיצב את הצליל הרך של העשור, והוא ממשיך להופיע ולהקליט עד היום. רבים מהשירים באלבום כתב טיילור בזמן ההחלמה, ואפשר לשמוע בהם אדם שמנסה להבין מה עבר עליו ולהמשיך הלאה.''',
'''שמעו את Fire and Rain בשקט, עם המילים. ואחר כך את שיר הנושא: שני שירים שמראים את שני הצדדים של טיילור, הכאב והנחמה, באותה גיטרה ובאותו קול.''',
], [
('Fire and Rain', 'שיר אישי וכואב על אובדן, התמכרות והחלמה, מהשירים הגדולים של שנות השבעים.'),
('Sweet Baby James', 'שיר הנושא: שיר ערש של קאובוי, רך ומנחם, שטיילור כתב לאחיין הקטן שלו.'),
('Country Road', 'שיר קצבי ושקט על הליכה לבד בדרך כפרית ועל חיפוש עצמי.'),
])
